#include "vincentftl/page_ftl.hpp"

#include <gtest/gtest.h>

#include "vincentftl/nand_emulator.hpp"

namespace vincentftl {
namespace {

// Page with different bytes for each seed.
PageData make_page(std::uint8_t seed) {
  PageData data;
  for (std::size_t i = 0; i < data.size(); ++i) {
    data[i] = static_cast<std::uint8_t>(seed + i);
  }
  return data;
}

// Real emulator, but we can make programs or reads fail.
class FailingDevice final : public NandDevice {
 public:
  explicit FailingDevice(NandEmulator& real) : real_(real) {}

  bool fail_program = false;
  bool fail_read = false;

  std::uint32_t block_count() const override { return real_.block_count(); }
  Status read_page(PhysicalPage page, PageData& data, PageSpare& spare) override {
    return fail_read ? Status::kBadAddress : real_.read_page(page, data, spare);
  }
  Status read_spare(PhysicalPage page, PageSpare& spare) override {
    return real_.read_spare(page, spare);
  }
  Status program_page(PhysicalPage page, const PageData& data, const PageSpare& spare) override {
    return fail_program ? Status::kProgramFailed : real_.program_page(page, data, spare);
  }
  Status erase_block(BlockNumber block) override { return real_.erase_block(block); }
  bool is_factory_bad(BlockNumber block) override { return real_.is_factory_bad(block); }

 private:
  NandEmulator& real_;
};

// No bad blocks, so every page counts.
TEST(PageFtl, CapacityIsAllPages) {
  NandEmulator device(4);
  PageFtl ftl(device);

  EXPECT_EQ(ftl.capacity(), 4 * kPagesPerBlock);
}

// Each bad block takes 64 pages off the capacity.
TEST(PageFtl, CapacitySkipsBadBlocks) {
  NandEmulator device(8, {BlockNumber{2}, BlockNumber{5}});
  PageFtl ftl(device);

  EXPECT_EQ(ftl.capacity(), 6 * kPagesPerBlock);
}

// Basic write, then read it back.
TEST(PageFtl, ReadReturnsWhatWasWritten) {
  NandEmulator device(4);
  PageFtl ftl(device);
  ASSERT_EQ(ftl.write(LogicalPage{3}, make_page(1)), FtlStatus::kOk);

  PageData out;
  ASSERT_EQ(ftl.read(LogicalPage{3}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(1));
}

// Nothing written yet, so there's no mapping to read from.
TEST(PageFtl, ReadOfUnwrittenPageFails) {
  NandEmulator device(4);
  PageFtl ftl(device);

  PageData out;
  EXPECT_EQ(ftl.read(LogicalPage{0}, out), FtlStatus::kNotWritten);
}

// Logical pages aren't written in order. Check the map doesn't mix them up.
TEST(PageFtl, PagesWrittenOutOfOrderStayApart) {
  NandEmulator device(4);
  PageFtl ftl(device);
  ASSERT_EQ(ftl.write(LogicalPage{200}, make_page(1)), FtlStatus::kOk);
  ASSERT_EQ(ftl.write(LogicalPage{5}, make_page(2)), FtlStatus::kOk);
  ASSERT_EQ(ftl.write(LogicalPage{64}, make_page(3)), FtlStatus::kOk);

  PageData out;
  ASSERT_EQ(ftl.read(LogicalPage{5}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(2));
  ASSERT_EQ(ftl.read(LogicalPage{64}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(3));
  ASSERT_EQ(ftl.read(LogicalPage{200}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(1));
}

// Write the same page twice, read should give the second one.
TEST(PageFtl, OverwriteReturnsNewData) {
  NandEmulator device(4);
  PageFtl ftl(device);
  ASSERT_EQ(ftl.write(LogicalPage{7}, make_page(1)), FtlStatus::kOk);
  ASSERT_EQ(ftl.write(LogicalPage{7}, make_page(2)), FtlStatus::kOk);

  PageData out;
  ASSERT_EQ(ftl.read(LogicalPage{7}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(2));
}

// An overwrite has to go to a new physical page.
TEST(PageFtl, OverwriteUsesANewPhysicalPage) {
  // NAND can't program the same page twice without an erase.
  NandEmulator device(4);
  PageFtl ftl(device);

  ASSERT_EQ(ftl.write(LogicalPage{0}, make_page(1)), FtlStatus::kOk);
  ASSERT_EQ(ftl.write(LogicalPage{0}, make_page(2)), FtlStatus::kOk);

  EXPECT_EQ(device.pages_programmed(), 2u);
}

// Edge case: capacity - 1 is the last valid address.
TEST(PageFtl, LastPageWorks) {
  NandEmulator device(4);
  PageFtl ftl(device);
  const LogicalPage last{ftl.capacity() - 1};

  ASSERT_EQ(ftl.write(last, make_page(1)), FtlStatus::kOk);

  PageData out;
  ASSERT_EQ(ftl.read(last, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(1));
}

// capacity is one past the end. The device shouldn't be touched.
TEST(PageFtl, WritePastEndIsBadAddress) {
  NandEmulator device(4);
  PageFtl ftl(device);

  EXPECT_EQ(ftl.write(LogicalPage{ftl.capacity()}, make_page(1)), FtlStatus::kBadAddress);
  EXPECT_EQ(device.pages_programmed(), 0u);
}

// Same bounds check, for reads.
TEST(PageFtl, ReadPastEndIsBadAddress) {
  NandEmulator device(4);
  PageFtl ftl(device);

  PageData out;
  EXPECT_EQ(ftl.read(LogicalPage{ftl.capacity()}, out), FtlStatus::kBadAddress);
}

// Bad blocks in the middle of the chip get skipped.
TEST(PageFtl, NeverWritesToBadBlocks) {
  // The emulator fails programs on bad blocks, so a full fill means we skipped them.
  NandEmulator device(6, {BlockNumber{1}, BlockNumber{4}});
  PageFtl ftl(device);

  for (std::uint32_t i = 0; i < ftl.capacity(); ++i) {
    ASSERT_EQ(ftl.write(LogicalPage{i}, make_page(static_cast<std::uint8_t>(i))), FtlStatus::kOk);
  }

  PageData out;
  ASSERT_EQ(ftl.read(LogicalPage{ftl.capacity() - 1}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(static_cast<std::uint8_t>(ftl.capacity() - 1)));
}

// Same, but the bad block is the last one on the chip.
TEST(PageFtl, BadBlockAtTheEndIsSkipped) {
  NandEmulator device(3, {BlockNumber{2}});
  PageFtl ftl(device);

  for (std::uint32_t i = 0; i < ftl.capacity(); ++i) {
    ASSERT_EQ(ftl.write(LogicalPage{i}, make_page(1)), FtlStatus::kOk);
  }
}

// Fill the device, then write once more. Should get kNoSpace.
TEST(PageFtl, NoSpaceWhenAllPagesAreUsed) {
  // No garbage collection yet, so an overwrite uses up a new page.
  NandEmulator device(2);
  PageFtl ftl(device);
  for (std::uint32_t i = 0; i < ftl.capacity(); ++i) {
    ASSERT_EQ(ftl.write(LogicalPage{i}, make_page(1)), FtlStatus::kOk);
  }

  EXPECT_EQ(ftl.write(LogicalPage{0}, make_page(2)), FtlStatus::kNoSpace);
}

// A write that fails for no space shouldn't lose the old data.
TEST(PageFtl, NoSpaceKeepsOldData) {
  NandEmulator device(2);
  PageFtl ftl(device);
  for (std::uint32_t i = 0; i < ftl.capacity(); ++i) {
    ASSERT_EQ(ftl.write(LogicalPage{i}, make_page(1)), FtlStatus::kOk);
  }
  ASSERT_EQ(ftl.write(LogicalPage{0}, make_page(2)), FtlStatus::kNoSpace);

  PageData out;
  ASSERT_EQ(ftl.read(LogicalPage{0}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(1));
}

// Program fails. We return kDeviceError and don't map the page.
TEST(PageFtl, ProgramFailureIsDeviceError) {
  NandEmulator real(4);
  FailingDevice device(real);
  PageFtl ftl(device);

  device.fail_program = true;
  EXPECT_EQ(ftl.write(LogicalPage{0}, make_page(1)), FtlStatus::kDeviceError);

  PageData out;
  EXPECT_EQ(ftl.read(LogicalPage{0}, out), FtlStatus::kNotWritten);
}

// Program fails on an overwrite. The old data should still be readable.
TEST(PageFtl, FailedOverwriteKeepsOldData) {
  NandEmulator real(4);
  FailingDevice device(real);
  PageFtl ftl(device);
  ASSERT_EQ(ftl.write(LogicalPage{0}, make_page(1)), FtlStatus::kOk);

  device.fail_program = true;
  ASSERT_EQ(ftl.write(LogicalPage{0}, make_page(2)), FtlStatus::kDeviceError);

  PageData out;
  ASSERT_EQ(ftl.read(LogicalPage{0}, out), FtlStatus::kOk);
  EXPECT_EQ(out, make_page(1));
}

// The device read fails after a good write.
TEST(PageFtl, ReadFailureIsDeviceError) {
  NandEmulator real(4);
  FailingDevice device(real);
  PageFtl ftl(device);
  ASSERT_EQ(ftl.write(LogicalPage{0}, make_page(1)), FtlStatus::kOk);

  device.fail_read = true;
  PageData out;
  EXPECT_EQ(ftl.read(LogicalPage{0}, out), FtlStatus::kDeviceError);
}

}  // namespace
}  // namespace vincentftl

/tactilevla/tactilevla-demo/css/base.css:
*, *::before, *::after { box-sizing: border-box; }
html {
  background: var(--wall-2);
  color-scheme: dark;
  -webkit-text-size-adjust: 100%;
  scrollbar-color: var(--hair-strong) transparent;
}
html.lenis, html.lenis body { height: auto; }
.lenis.lenis-smooth { scroll-behavior: auto !important; }
.lenis.lenis-stopped { overflow: hidden; }
html.is-loading { overflow: hidden; }

body {
  margin: 0;
  min-height: 100vh;
  font-family: "Archivo", system-ui, -apple-system, "Segoe UI", sans-serif;
  font-stretch: 100%;
  font-weight: 400;
  font-size: var(--fs-body);
  line-height: 1.6;
  color: var(--ivory);
  background: transparent;
  overflow-x: clip;
}
html::before { /* fixed backdrop as an element: background-attachment: fixed misbehaves on iOS */
  content: ""; position: fixed; inset: 0; z-index: -1; pointer-events: none;
  background: radial-gradient(120% 90% at 72% 38%, var(--wall) 0%, var(--wall-2) 70%);
}
img, video, canvas, svg { display: block; max-width: 100%; }
h1, h2, h3, p, ul, ol, dl, dd, figure { margin: 0; padding: 0; }
ul, ol { list-style: none; }
button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
a { color: inherit; text-decoration-color: var(--hair-strong); text-underline-offset: 0.2em; }
a:hover { text-decoration-color: var(--noodle); }
[hidden] { display: none !important; }
:focus { outline: none; }
:focus-visible { outline: 2px solid var(--noodle); outline-offset: 3px; border-radius: 2px; }
section:focus { outline: none; }
::selection { background: var(--noodle); color: var(--on-accent); }

.num, dd, .counter-n, .stat-num { font-variant-numeric: tabular-nums; }
.sr-only {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.skip {
  position: fixed; left: 1rem; top: -4rem; z-index: 100; padding: 0.6rem 1rem;
  background: var(--noodle); color: var(--on-accent); font-weight: 700; text-decoration: none;
}
.skip:focus { top: 1rem; }

/* Fixed 3D stage */
#stage { position: fixed; inset: 0; width: 100%; height: 100%; z-index: 0; }
#stage { transition: opacity 0.8s ease; }
.no-stage #stage { opacity: 0; pointer-events: none; } /* stays laid out so a slow stage can size itself, then fades in */
@media (prefers-reduced-motion: reduce) { #stage { transition: none; } }
.no-stage body::before, .stage-fading body::before {
  content: ""; position: fixed; inset: 0; z-index: 0;
  background:
    linear-gradient(rgba(var(--veil-rgb), 0.78), rgba(var(--veil-rgb), 0.9)),
    url("../media/poster-act-b2.jpg") center 32% / cover no-repeat;
  background:
    linear-gradient(rgba(var(--veil-rgb), 0.78), rgba(var(--veil-rgb), 0.9)),
    image-set(url("../media/poster-act-b2.webp") type("image/webp"), url("../media/poster-act-b2.jpg") type("image/jpeg")) center 32% / cover no-repeat;
}
.scrim { /* sits above the canvas, below the content: keeps the text side legible, the scene continuous */
  position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background: linear-gradient(90deg, rgba(var(--veil-rgb), 0.65) 0%, rgba(var(--veil-rgb), 0.38) 30%, rgba(var(--veil-rgb), 0) 55%);
}
.no-stage .scrim { display: none; }

main { position: relative; z-index: 1; }
.panel { text-shadow: 0 1px 14px rgba(var(--veil-rgb), 0.6); }

/* Type */
.display {
  font-stretch: 112%;
  font-weight: 780;
  font-size: var(--fs-h2);
  line-height: 1.02;
  letter-spacing: -0.012em;
  text-wrap: balance;
  margin-bottom: 1.4rem;
}
p + p { margin-top: 1rem; }
.caption, figcaption { font-size: var(--fs-caption); line-height: 1.5; color: var(--caption); }
.lede { font-size: clamp(1.0625rem, 1.25vw, 1.25rem); color: var(--ivory); max-width: 36rem; text-wrap: pretty; }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 3rem; padding: 0 1.5rem; border-radius: 999px;
  font-weight: 650; font-stretch: 100%; text-decoration: none; font-size: 1rem;
  transition: background-color 0.25s, color 0.25s, transform 0.25s var(--ease-out), box-shadow 0.25s;
}
.btn--primary { background: var(--noodle); color: var(--on-accent); box-shadow: 0 10px 40px -12px rgba(var(--noodle-rgb), 0.55); }
.btn--primary:hover { filter: brightness(1.08) saturate(1.05); transform: translateY(-1px); }
.btn--ghost { box-shadow: inset 0 0 0 1px var(--hair-strong); }
.btn--ghost:hover { box-shadow: inset 0 0 0 1px var(--ivory); }
.actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-top: 2rem; }

/* Top bar */
.topbar {
  position: fixed; inset: 0 0 auto 0; z-index: 20; height: var(--topbar-h);
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding: 0 var(--gutter);
  background: rgba(var(--veil-rgb), 0.62);
  -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);
  transition: box-shadow 0.4s;
}
.topbar.is-scrolled { box-shadow: 0 1px 0 var(--hair); }
.wordmark { font-stretch: 125%; font-weight: 760; letter-spacing: -0.01em; text-decoration: none; font-size: 1rem; white-space: nowrap; }
.topbar nav { display: flex; gap: clamp(0.85rem, 2.4vw, 1.9rem); font-size: 0.875rem; }
.topbar nav a { color: var(--dim); text-decoration: none; transition: color 0.2s; white-space: nowrap; padding: 0.4rem 0; display: inline-flex; align-items: center; min-height: 2.75rem; }
.topbar nav a:hover { color: var(--ivory); }
@media (max-width: 420px) {
  .wordmark { font-size: 0.875rem; }
  .topbar nav { gap: 0.9rem; font-size: var(--fs-caption); }
  .topbar nav a:nth-child(2) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
  .btn { transition: none; }
}
/* Persistent honesty badge: quiet, out of the way of the text */
.stage-badge {
  position: fixed; right: var(--gutter); bottom: 1.1rem; z-index: 15; margin: 0; pointer-events: none;
  font-size: var(--fs-micro); line-height: 1; color: rgba(var(--ivory-rgb), 0.85);
  padding: 0.4rem 0.7rem; border-radius: 999px; background: rgba(var(--veil-rgb), 0.6);
  -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
  transition: opacity 0.5s;
}
.no-stage .stage-badge, .is-loading .stage-badge, body[data-chapter="film"] .stage-badge, body[data-chapter="limits"] .stage-badge { opacity: 0; }
@media (max-width: 820px) {
  .stage-badge {
    right: auto; left: var(--gutter); top: auto; bottom: calc(env(safe-area-inset-bottom, 0px) + 0.7rem); font-size: 0.6875rem;
  }
  body[data-chapter="hero"] .stage-badge { opacity: 0; }
  body[data-chapter="sandbox"] .stage-badge { bottom: auto; top: calc(var(--topbar-h) + 0.6rem); }
}

/* Chapter progress rail (desktop) */
.rail { position: fixed; top: 0; right: 0; bottom: 0; width: 2px; z-index: 16; pointer-events: none; background: rgba(var(--ivory-rgb), 0.07); }
.rail i { position: absolute; inset: 0; background: var(--noodle); transform-origin: 50% 0; transform: scaleY(var(--p, 0)); opacity: 0.9; }
.rail b { position: absolute; right: 0; width: 6px; height: 1px; background: rgba(var(--ivory-rgb), 0.4); }
.is-loading .rail, .no-stage .rail { opacity: 0; }
@media (max-width: 820px) { .rail { display: none; } }
@media (prefers-reduced-motion: reduce) { .stage-badge { transition: none; } }

/* Hardware-acceleration note: a quiet pill, bottom-left, dismissible */
.gl-note {
  position: fixed; left: var(--gutter); bottom: calc(env(safe-area-inset-bottom, 0px) + 1.1rem); z-index: 30;
  display: flex; align-items: flex-start; gap: 0.35rem; max-width: min(34rem, calc(100vw - 2 * var(--gutter)));
  padding: 0.6rem 0.4rem 0.6rem 1.1rem; border-radius: 1.4rem;
  background: rgba(var(--veil-rgb), 0.86); box-shadow: 0 0 0 1px var(--hair-strong), 0 12px 40px -12px var(--shadow);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
}
.gl-note p { margin: 0; font-size: var(--fs-caption); line-height: 1.45; color: var(--ivory); padding-top: 0.15rem; }
.gl-note button { flex: none; width: 2.25rem; height: 2.25rem; display: grid; place-items: center; border-radius: 50%; }
.gl-note button:hover { background: rgba(var(--ivory-rgb), 0.12); }
.gl-note svg { width: 1rem; height: 1rem; fill: none; stroke: var(--ivory); stroke-width: 1.8; stroke-linecap: round; }

/tactilevla/tactilevla-demo/css/chapters:
/* Chapter scaffolding. <main> and sections let pointer events through to the canvas (3D hover/click);
   panels and interactive blocks take them back. */
main, .chapter, .pin { pointer-events: none; }
.panel, .strip-wrap, .footer, .hero-note, .hero-inset { pointer-events: auto; }
#stage { touch-action: pan-y; }

.chapter {
  position: relative; min-height: 100vh; min-height: 100svh;
  display: flex; align-items: center;
  padding: calc(var(--topbar-h) + 2rem) var(--gutter) var(--space-section);
}
.panel { width: 100%; max-width: var(--col); position: relative; }
.panel--wide { max-width: var(--wide); }
.panel p { max-width: 60ch; text-wrap: pretty; }
.panel .lede { max-width: min(34rem, 100%); }

/* Hero */
.chapter--hero { padding-bottom: 7rem; }
.chapter--hero .panel { max-width: min(46vw, 60rem); }
.hero-title {
  font-stretch: 125%; font-weight: 800; font-size: clamp(2.4rem, 4vw, 6.6rem);
  line-height: 0.94; letter-spacing: -0.015em; margin-bottom: 1.8rem; text-wrap: balance;
}
.hero-note {
  position: absolute; left: var(--gutter); bottom: 2.25rem; max-width: 26rem;
  font-size: var(--fs-caption); line-height: 1.5; color: var(--dim);
}
.hero-inset { width: 200px; margin: 1.75rem 0 0; }
.hero-inset figcaption { margin-top: 0.5rem; font-size: var(--fs-micro); color: rgba(var(--ivory-rgb), 0.78); }

/* Tall pinned chapters: sticky viewport, progress scrubbed by scroll */
.chapter--tall { display: block; padding: 0; height: 290vh; }
.chapter--data { height: 320vh; }
.chapter--pin { display: block; padding: 0; height: 170vh; }
.chapter--test { min-height: 140vh; }
.pin {
  position: sticky; top: 0; height: 100vh; height: 100svh;
  display: flex; align-items: center; padding: calc(var(--topbar-h) + 0.5rem) var(--gutter) 2rem;
  overscroll-behavior-y: none;
}
.scrub-in, [data-scrub-in] { will-change: opacity; }

/* Arm: three beats stacked in one cell, crossfaded by the scrub (JS adds .beats-on) */
.beats-on .beats { display: grid; }
.beats-on .beat { grid-area: 1 / 1; align-self: start; }
.stat-n {
  display: block; font-stretch: 125%; font-weight: 900; color: var(--noodle);
  font-size: clamp(3.4rem, 7.2vw, 7rem); line-height: 0.92; letter-spacing: -0.03em; white-space: nowrap;
}
.stat-l { display: block; margin-top: 0.9rem; max-width: 22rem; color: var(--ivory); }

@media (max-height: 760px) and (min-width: 821px) {
  .display { margin-bottom: 1rem; }
  .chapter--data .display { font-size: clamp(1.8rem, 3vw, 2.6rem); }
}
.chapter--data .panel { max-width: min(38rem, 41vw); }
.chapter--data .panel p { max-width: min(34rem, 100%); }

/* Portrait: the 3D owns the top ~46%. Text sits low on a scrim, with clear runs of scene between panels. */
@media (max-width: 820px) {
  :root { --fs-body: 1rem; --col: none; --wide: none; }
  .scrim { display: none; }
  .panel { text-shadow: none; }
  .chapter { padding: calc(var(--topbar-h) + 1rem) 0 0; align-items: flex-end; min-height: 135vh; min-height: 135svh; }
  .chapter--tall { padding: 0; min-height: 0; height: 220vh; height: 220svh; }
  .chapter--data { height: 240vh; height: 240svh; }
  .chapter--pin, .chapter--test { height: auto; min-height: 135svh; padding: calc(var(--topbar-h) + 1rem) 0 0; align-items: flex-end; }
  .chapter--pin .pin { position: static; display: block; height: auto; padding: 0; width: 100%; }
  .pin { padding: calc(var(--topbar-h) + 0.5rem) 0 0; align-items: flex-end; }
  .panel, .chapter--data .panel {
    max-width: none; padding: 3rem var(--gutter) 3.4rem;
    background: linear-gradient(to bottom, rgba(var(--veil-rgb), 0) 0, rgba(var(--veil-rgb), 0.6) 2.25rem, rgba(var(--veil-rgb), 0.86) 4.5rem, rgba(var(--veil-rgb), 0.9) 100%);
  }
  .pin .panel { padding-bottom: 3.4rem; padding-top: 3rem; }
  .display { font-size: clamp(1.75rem, 8vw, 2.4rem); }

  .chapter--hero { min-height: 100vh; min-height: 100svh; padding: 0; }
  .chapter--hero .panel {
    padding: 7rem var(--gutter) 4.6rem; max-width: none;
    background: linear-gradient(to top, rgba(var(--veil-rgb), 0.94) 0, rgba(var(--veil-rgb), 0.88) 62%, rgba(var(--veil-rgb), 0) 100%);
  }
  .hero-title { font-size: clamp(1.9rem, 8.6vw, 3.2rem); margin-bottom: 1rem; }
  .chapter--hero .lede { font-size: 0.9375rem; line-height: 1.5; }
  .chapter--hero .actions { flex-wrap: nowrap; gap: 0.5rem; margin-top: 1.1rem; }
  .chapter--hero .btn { min-height: 2.75rem; padding: 0 1rem; font-size: 0.875rem; white-space: nowrap; }
  .hero-note { left: var(--gutter); right: var(--gutter); bottom: 1rem; max-width: none; font-size: var(--fs-micro); line-height: 1.4; }
  .hero-inset { display: none; }
  .chapter--tall .panel > p, .chapter--tall .beat { font-size: 0.9375rem; line-height: 1.5; }
  .stat-n { font-size: clamp(3.2rem, 17vw, 4.6rem); }

  .chapter--data .pin .panel { padding-top: 2.75rem; padding-bottom: 3.2rem; }
  .chapter--data .display { font-size: 1.45rem; margin-bottom: 0.6rem; }
  .chapter--data .panel > p { font-size: 0.8125rem; line-height: 1.45; margin-top: 0.6rem; }
  .chapter--data .counter-main { font-size: clamp(1.6rem, 7.6vw, 2.1rem); }
  .chapter--data .counter-sub { font-size: 0.875rem; margin-top: 0.35rem; min-height: 0; }
  .chapter--data .counter-note { font-size: var(--fs-micro); margin-top: 0.35rem; }
  .chapter--data .stats { margin-top: 0.7rem; }
  .chapter--data .stats dd { font-size: 1.25rem; }
  .chapter--data .closing { margin-top: 0.6rem; font-size: 1.15rem; }
}
@media (max-width: 820px) and (max-height: 720px) {
  .chapter--tall .display { font-size: 1.6rem; margin-bottom: 0.7rem; }
}
@media (max-width: 360px) { .chapter--hero .btn { padding: 0 0.8rem; font-size: 0.8125rem; } }

/* No WebGL: the page still reads fully over the darkened footage */
.no-stage .hero-note { display: none; }
@media (max-height: 760px) and (min-width: 821px) { .hero-inset { display: none; } } /* short windows: the copy comes first */

/tactilevla/tactilevla-demo/css/componen:
/* ---- Data chapter ---- */
.counter { margin-top: 1.6rem; padding-top: 1.1rem; border-top: 1px solid var(--hair); display: grid; display: block; }
.counter-main {
  font-stretch: 125%; font-weight: 780; font-size: clamp(1.7rem, 3.4vw, 3.4rem); line-height: 1; letter-spacing: -0.02em;
  white-space: nowrap; margin: 0;
}
.counter-lbl { display: inline-block; max-width: 6em; overflow: hidden; vertical-align: bottom; transition: max-width 0.5s var(--ease-out), opacity 0.4s; }
.counter.is-full .counter-lbl { max-width: 0; opacity: 0; margin-right: -0.25em; }
.counter-n { display: inline-block; min-width: 2.1ch; text-align: right; color: var(--noodle); }
.counter-of { color: var(--dim); font-weight: 600; }
.counter-note { font-size: var(--fs-caption); line-height: 1.45; color: var(--dim); margin-top: 0.6rem; max-width: 30rem; }
.counter-sub { grid-column: 1; font-size: 1rem; color: var(--dim); margin-top: 0.5rem; font-variant-numeric: tabular-nums; min-height: 1.6em; }
.stats { display: grid; grid-template-columns: repeat(3, auto); justify-content: start; margin-top: 1.4rem; }
.stats > div { padding: 0 clamp(0.9rem, 2.2vw, 1.75rem); border-left: 1px solid var(--hair); display: flex; flex-direction: column-reverse; }
.stats > div:first-child { padding-left: 0; border-left: 0; }
.stats dd { font-stretch: 112%; font-weight: 760; font-size: clamp(1.4rem, 2.4vw, 2rem); line-height: 1.1; letter-spacing: -0.02em; }
.stats dt { font-size: var(--fs-caption); color: var(--dim); }
.closing { margin-top: 1.4rem; font-stretch: 125%; font-weight: 780; letter-spacing: -0.015em; line-height: 1.05; color: var(--held); font-size: clamp(1.6rem, 3.2vw, 3.4rem); text-wrap: balance; }
@media (max-width: 820px) {
  .counter { margin-top: 1rem; padding-top: 0.8rem; }
  .counter-main { font-size: clamp(1.7rem, 8.4vw, 2.3rem); }
  .stats { margin-top: 1rem; }
  .closing { margin-top: 0.8rem; font-size: 1rem; }
}

/* ---- Cameras ---- */
.feed { margin-top: 2rem; }
.feed-screen {
  position: relative; background: #0a0c0d; padding: 0.55rem; border-radius: 4px;
  box-shadow: 0 0 0 1px var(--hair), 0 40px 80px -30px var(--shadow), inset 0 0 0 1px rgba(255,255,255,0.03);
}
.feed-screen video { display: block; width: 100%; height: auto; border-radius: 1px; }
.feed-screen .clip-play { z-index: 2; }
.feed-screen::after { /* faint vignette so it reads as a display, not a sticker */
  content: ""; position: absolute; inset: 0.55rem; pointer-events: none;
  box-shadow: inset 0 0 40px rgba(0,0,0,0.45);
}
.feed-tag {
  position: absolute; bottom: 1.1rem; z-index: 1; font-size: var(--fs-micro); line-height: 1; padding: 0.32rem 0.55rem;
  background: rgba(10,12,13,0.72); color: rgba(243, 234, 214, 0.9); border-radius: 999px; font-variant-numeric: tabular-nums;
}
.feed-tag--l { left: 1.1rem; }
.feed-tag--r { right: 1.1rem; }
.feed figcaption { margin-top: 0.85rem; }

/* ---- Policies ---- */
.seg {
  display: inline-grid; grid-template-columns: 1fr 1fr; padding: 3px; border-radius: 999px;
  background: rgba(var(--veil-rgb), 0.78); box-shadow: inset 0 0 0 1px var(--hair-strong); margin-bottom: 1.6rem;
}
.seg-btn {
  min-width: 7.5rem; min-height: 2.75rem; padding: 0 1.4rem; border-radius: 999px; font-weight: 650; font-stretch: 100%;
  color: var(--seg-idle); transition: background-color 0.3s var(--ease-out), color 0.3s;
}
.seg-btn:hover { color: var(--ivory); }
.seg-btn[aria-pressed="true"] { background: var(--noodle); color: var(--on-accent); }
.specs { margin-bottom: 1.4rem; animation: spec-in 0.5s var(--ease-out); }
@keyframes spec-in { from { opacity: 0; transform: translateY(6px); } }
.spec-lead { font-stretch: 112%; font-weight: 780; font-size: clamp(1.6rem, 2.7vw, 2.3rem); line-height: 1.05; letter-spacing: -0.02em; margin-bottom: 0.9rem; }
.specs li { padding: 0.55rem 0; border-top: 1px solid var(--hair); font-variant-numeric: tabular-nums; }
.specs li:last-child { border-bottom: 1px solid var(--hair); }

/* ---- Test chapter ---- */
.giant-cell {
  font-stretch: 125%; font-weight: 900; line-height: 0.78; letter-spacing: -0.045em;
  font-size: clamp(8rem, 16vw, 15rem); color: var(--held); margin: 0 0 0.05em -0.05em; max-width: none !important;
  background: linear-gradient(to bottom, var(--held) 35%, rgba(var(--held-rgb), 0.4));
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  -webkit-user-select: none; user-select: none;
}
.clip-row { display: flex; flex-direction: column; align-items: flex-start; gap: 0.8rem; margin-top: 1.6rem; }
.clip-row .clip { width: min(18.75rem, 100%); flex: none; }
.clip { position: relative; background: #0a0c0d; border-radius: 3px; overflow: hidden; box-shadow: 0 0 0 1px var(--hair), 0 30px 60px -25px var(--shadow); aspect-ratio: 9 / 16; }
.clip--wide { aspect-ratio: 848 / 464; }
.clip video { width: 100%; height: 100%; object-fit: cover; }
.clip-play, .reel-play {
  position: absolute; inset: 0; display: grid; place-items: center; background: linear-gradient(to top, rgba(10,12,13,0.5), transparent 50%);
}
.clip-play svg, .reel-play svg { width: 3.4rem; height: 3.4rem; padding: 1rem 0.85rem 1rem 1.15rem; border-radius: 50%; background: var(--noodle); fill: var(--on-accent); transition: transform 0.3s var(--ease-out); }
.clip-play:hover svg, .reel-play:hover svg { transform: scale(1.08); }

/* ---- Results ---- */
.rows { display: grid; gap: 2rem; margin: 0.5rem 0 1.8rem; }
.row-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; margin-bottom: 0.7rem; }
.row-head h3 { font-stretch: 100%; font-weight: 700; font-size: 1.125rem; letter-spacing: -0.005em; }
.row-score { font-size: 1rem; color: var(--dim); }
.row-score .num { font-stretch: 112%; font-weight: 780; font-size: 1.35rem; color: var(--ivory); }
.dots { display: grid; grid-template-columns: repeat(20, 1fr); gap: clamp(3px, 0.7vw, 6px); margin-bottom: 1.1rem; }
.dot { aspect-ratio: 1; border-radius: 50%; box-shadow: inset 0 0 0 1.5px rgba(var(--ivory-rgb), 0.4); transition: background-color 0.9s ease, box-shadow 0.9s ease; }
.dot.is-hit { background: var(--noodle); box-shadow: none; }
.dots.is-armed .dot.is-hit:not(.is-on) { background: transparent; box-shadow: inset 0 0 0 1.5px rgba(var(--ivory-rgb), 0.4); }
.track { position: relative; height: 0.625rem; background: rgba(var(--ivory-rgb), 0.09); border-radius: 999px; }
.range {
  position: absolute; top: 0; bottom: 0; left: calc(var(--lo) * 1%); width: calc((var(--hi) - var(--lo)) * 1%);
  background: rgba(var(--noodle-rgb), 0.62); border-radius: 999px; transform-origin: calc((var(--pt) - var(--lo)) / (var(--hi) - var(--lo)) * 100%) 50%;
  transition: transform 0.9s var(--ease-out) 0.3s, opacity 0.6s 0.3s;
}
.interval.is-armed .range { transform: scaleX(0); opacity: 0; }
.point { position: absolute; top: -0.3rem; bottom: -0.3rem; left: calc(var(--pt) * 1%); width: 3px; margin-left: -1.5px; background: var(--ivory); border-radius: 2px; }
.ticks { display: flex; justify-content: space-between; font-size: var(--fs-micro); color: var(--dim); margin-top: 0.4rem; font-variant-numeric: tabular-nums; }
.ci { display: flex; justify-content: space-between; gap: 1rem; font-size: var(--fs-caption); color: var(--dim); margin-top: 0.4rem; }
.ci .num { color: var(--ivory); font-weight: 600; }
.ci-r { text-align: right; }
.panel .ci, .panel .row-score, .panel .counter-main, .panel .counter-sub { max-width: none; }
@media (max-width: 820px) { .feed-tag { font-size: var(--fs-micro); bottom: 0.9rem; } .feed-tag--l { left: 0.9rem; } .feed-tag--r { right: 0.9rem; } }
@media (max-width: 820px) { .clip-row .clip { width: 100%; } }

/* Results payoff headline and task line */
.results-title { font-stretch: 125%; font-weight: 800; font-size: clamp(3.2rem, 6.1vw, 6.4rem); line-height: 0.94; letter-spacing: -0.02em; margin-bottom: 1.6rem; }
.results-title span { display: block; white-space: nowrap; }
.task { color: var(--ivory); margin-bottom: 1.6rem; max-width: 34rem; }
.clip--inset { width: 200px; aspect-ratio: 420 / 249; }
.clip--inset .clip-play svg { width: 2.6rem; height: 2.6rem; padding: 0.75rem 0.6rem 0.75rem 0.9rem; }
@media (max-width: 820px) { .results-title { font-size: clamp(2.8rem, 15vw, 4.2rem); } }

/* Feathered veil behind text on desktop so bright scenes never fight the copy */
@media (min-width: 821px) {
  .chapter:not(.chapter--hero):not(.chapter--film) .panel::before {
    content: ""; position: absolute; z-index: -1; pointer-events: none; inset: -3.5rem -5rem -3.5rem -9rem;
    background: radial-gradient(ellipse 75% 62% at 34% 50%, rgba(var(--veil-rgb), 0.72), rgba(var(--veil-rgb), 0.5) 55%, rgba(var(--veil-rgb), 0) 100%);
  }
  .chapter--data .panel::before { inset: -3rem -3rem -3rem -9rem; }
}
/* Reduced motion: no scrub-driven reveals, no entrance animation */
@media (prefers-reduced-motion: reduce) {
  .specs { animation: none; }
  .counter-lbl { transition: none; }
  [data-scrub-in] { opacity: 1 !important; transform: none !important; }
}

/* Always-visible pause/play toggle on looping clips */
.clip { --tg: 2.75rem; }
.clip-toggle {
  position: absolute; right: 0.15rem; bottom: 0.15rem; z-index: 4; width: var(--tg, 2.75rem); height: var(--tg, 2.75rem);
  display: grid; place-items: center; border-radius: 50%;
}
.clip-toggle svg { width: 1.6rem; height: 1.6rem; padding: 0.4rem; border-radius: 50%; fill: var(--media-ink); background: rgba(10, 12, 13, 0.72); transition: background-color 0.2s; }
.clip-toggle:hover svg { background: rgba(10, 12, 13, 0.92); }
.feed-screen { position: relative; }
.feed-screen .clip-toggle { right: 0.7rem; top: 0.7rem; bottom: auto; }
.clip--inset .clip-toggle { --tg: 2.25rem; right: 0; bottom: 0; }
.clip--inset .clip-toggle svg { width: 1.4rem; height: 1.4rem; padding: 0.3rem; }

/tactilevla/tactilevla-demo/css/film.css:
.chapter--film {
  display: block; padding: calc(var(--topbar-h) + 3rem) 0 var(--space-section); min-height: 0; isolation: isolate;
}
.chapter--film::before { /* soft veil behind the heading column only; the reels and the scene stay crisp */
  content: ""; position: absolute; inset: 0 auto auto 0; width: 60%; height: 26rem; z-index: -1; pointer-events: none;
  background: rgba(var(--veil-rgb), 0.55); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 8rem, #000 calc(100% - 6rem), transparent), linear-gradient(to right, #000 50%, transparent);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to bottom, transparent, #000 8rem, #000 calc(100% - 6rem), transparent), linear-gradient(to right, #000 50%, transparent);
  mask-composite: intersect;
}
.film-head { margin-left: var(--gutter); width: auto; }
.swipe-hint { display: none; }
.strip-wrap { position: relative; margin-top: 0.5rem; }
.strip-nav { position: absolute; right: var(--gutter); top: 0.5rem; display: flex; gap: 0.5rem; z-index: 2; }
.nav-btn {
  width: 3rem; height: 3rem; border-radius: 50%; display: grid; place-items: center;
  box-shadow: inset 0 0 0 1px var(--hair-strong); transition: background-color 0.25s, box-shadow 0.25s;
}
.nav-btn:hover { background: rgba(var(--ivory-rgb), 0.1); box-shadow: inset 0 0 0 1px var(--ivory); }
.nav-btn svg { width: 1.3rem; height: 1.3rem; fill: none; stroke: var(--ivory); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }

.strip {
  display: flex; align-items: flex-start; gap: clamp(2rem, 4.5vw, 4.5rem);
  overflow-x: auto; overscroll-behavior-x: contain; scroll-snap-type: x mandatory;
  padding: 6.5rem var(--gutter) 2.5rem; scroll-padding-inline: var(--gutter);
  scrollbar-width: none; -ms-overflow-style: none;
}
.strip::-webkit-scrollbar { display: none; }
.strip-progress { height: 2px; margin: 0 var(--gutter); background: rgba(var(--ivory-rgb), 0.12); position: relative; }
.strip-progress i { position: absolute; inset: 0; background: var(--noodle); transform-origin: 0 50%; transform: scaleX(var(--sp, 0.2)); }

.reel { flex: none; position: relative; width: clamp(14.5rem, 21vw, 19rem); scroll-snap-align: start; }
.reel:nth-child(even) { margin-top: clamp(3rem, 7vw, 6rem); }
.reel::before { /* the cell name, huge and outlined, sitting behind the frame */
  content: attr(data-cell); position: absolute; z-index: 0; left: -0.06em; top: -0.84em;
  font-stretch: 112%; font-weight: 900; font-size: clamp(6rem, 10vw, 9rem); line-height: 1; letter-spacing: -0.04em;
  color: transparent; -webkit-text-stroke: 1.5px var(--c); pointer-events: none;
  filter: drop-shadow(0 0 6px rgba(10, 12, 13, 0.7));
}
.reel--held { --c: var(--held); }
.reel--trained { --c: rgba(var(--trained-rgb), 0.85); }
.reel--wide { width: clamp(24rem, 40vw, 34rem); margin-top: clamp(3rem, 7vw, 6rem); }
.reel--wide::before { display: none; }
.reel--wide .clip { width: 100%; }
.reel figure { position: relative; z-index: 1; }
.frame {
  position: relative; aspect-ratio: 9 / 16; background: #0a0c0d; overflow: hidden; border-radius: 3px;
  box-shadow: 0 40px 70px -30px var(--shadow); transition: transform 0.6s var(--ease-out), box-shadow 0.6s;
}
.reel--held .frame { box-shadow: 0 0 0 1px rgba(var(--held-rgb), 0.55), 0 40px 70px -30px var(--shadow); }
.reel--trained .frame { box-shadow: 0 0 0 1px rgba(var(--trained-rgb), 0.4), 0 40px 70px -30px var(--shadow); }
.reel:hover .frame, .reel:focus-within .frame { transform: translateY(-6px); }
.frame video { width: 100%; height: 100%; object-fit: cover; }
.reel.is-previewing .reel-play svg { opacity: 0; }
.reel.is-engaged .reel-play { display: none; }
.reel figcaption { display: flex; align-items: center; gap: 0.6rem; margin-top: 0.85rem; font-size: 0.9375rem; color: var(--ivory); flex-wrap: wrap; }
.reel figcaption strong { font-weight: 650; margin-right: -0.3rem; }
.reel--wide figcaption { color: var(--dim); font-size: var(--fs-caption); }
.tag { font-size: var(--fs-micro); font-weight: 650; line-height: 1; padding: 0.3rem 0.6rem; border-radius: 999px; }
.tag--held { color: var(--held-text); box-shadow: inset 0 0 0 1px var(--held); }
.tag--trained { color: var(--trained-text); box-shadow: inset 0 0 0 1px rgba(var(--trained-rgb), 0.7); }

/* Minimal custom controls, shown once a clip is engaged */
.vc {
  position: absolute; left: 0; right: 0; bottom: 0; display: flex; align-items: center; gap: 0.5rem;
  padding: 1.6rem 0.6rem 0.6rem; background: linear-gradient(to top, rgba(10,12,13,0.85), rgba(10,12,13,0));
  opacity: 0; transition: opacity 0.3s; z-index: 3;
}
.is-engaged .vc, .vc:focus-within { opacity: 1; }
.vc button { width: 2.75rem; height: 2.75rem; display: grid; place-items: center; flex: none; border-radius: 50%; }
.vc button:hover { background: rgba(243, 234, 214, 0.16); }
.vc svg { width: 1.25rem; height: 1.25rem; fill: var(--media-ink); }
.vc-bar { flex: 1; height: 2.75rem; display: flex; align-items: center; cursor: pointer; touch-action: none; }
.vc-bar span { display: block; position: relative; width: 100%; height: 3px; background: rgba(243, 234, 214, 0.32); border-radius: 2px; }
.vc-bar i { position: absolute; inset: 0; background: var(--noodle); border-radius: 2px; transform-origin: 0 50%; transform: scaleX(var(--t, 0)); }

@media (max-width: 820px) {
  .chapter--film { padding-top: calc(var(--topbar-h) + 2rem); }
  .film-head { margin: 0; width: 100%; }
  .swipe-hint { display: block; margin-top: 0.8rem; font-size: var(--fs-caption); color: var(--accent-text); }
  .strip { padding-top: 5.5rem; gap: 1.75rem; scroll-snap-type: x mandatory; }
  .reel { width: 78vw; max-width: 19rem; }
  .reel--wide { width: 78vw; max-width: 24rem; }
  .reel:nth-child(even) { margin-top: 2.5rem; }
  .reel::before { font-size: 5rem; left: 0; }
}
@media (prefers-reduced-motion: reduce) { .frame, .vc { transition: none; } .reel:hover .frame { transform: none; } }
.nav-btn[aria-disabled="true"] { opacity: 0.35; cursor: default; }
.vc-cc { font-size: var(--fs-micro); font-weight: 700; letter-spacing: 0.02em; color: var(--media-ink); }
.vc .vc-cc[aria-pressed="true"] { background: var(--noodle); color: var(--on-accent); }
@media (max-width: 820px) {
  .strip-nav { display: flex; right: var(--gutter); top: 0.25rem; }
  .nav-btn { width: 2.75rem; height: 2.75rem; }
}

@media (max-width: 820px) {
  .chapter--film::before { width: 100%; height: 22rem; -webkit-mask-image: linear-gradient(to bottom, transparent, #000 6rem, #000 calc(100% - 5rem), transparent); mask-image: linear-gradient(to bottom, transparent, #000 6rem, #000 calc(100% - 5rem), transparent); -webkit-mask-composite: source-over; mask-composite: add; }
}

/tactilevla/tactilevla-demo/css/loader.c:
.loader {
  position: fixed; inset: 0; z-index: 90; display: grid; place-content: center; justify-items: center; gap: 1.1rem;
  background: var(--wall-2);
}
.loader-ring { width: 11rem; height: 11rem; overflow: visible; will-change: transform, opacity; }
.loader-ring circle { fill: none; transform: rotate(-90deg); transform-origin: 60px 60px; }
.loader-track { stroke: rgba(var(--ring-rgb), 0.14); stroke-width: 2.5; }
.loader-fill {
  stroke: var(--ring-color); stroke-width: 2.5; stroke-linecap: round; stroke-dasharray: 326.73; stroke-dashoffset: 326.73;
  filter: drop-shadow(0 0 3px rgba(var(--ring-rgb), 0.75)) drop-shadow(0 0 9px rgba(var(--ring-rgb), 0.45));
}
.loader-word { font-stretch: 125%; font-weight: 760; font-size: 1.05rem; letter-spacing: -0.005em; color: var(--ivory); margin-top: 0.4rem; }
.loader-pct { font-size: var(--fs-caption); color: var(--dim); font-variant-numeric: tabular-nums; min-width: 3ch; text-align: center; margin-top: -0.6rem; }
/* Pre-reveal states so nothing flashes before the orchestrated entrance */
.is-loading .hero-title .line > span { transform: translateY(118%); }
.is-loading .hero-fade { opacity: 0; }
.hero-title .line { display: block; overflow: hidden; padding-bottom: 0.18em; margin-bottom: -0.18em; }
.hero-title .line > span { display: block; will-change: transform; }

/tactilevla/tactilevla-demo/css/stage-la:
/* Labels rendered by the 3D stage (CSS2DRenderer). The stage owns positioning; this owns looks. */
.stage-label {
  pointer-events: none; white-space: nowrap;
  font-family: "Archivo", system-ui, sans-serif; font-stretch: 100%; font-weight: 500;
  font-size: 0.75rem; line-height: 1; letter-spacing: 0.01em; font-variant-numeric: tabular-nums;
  color: rgba(var(--ivory-rgb), 0.8);
  background: rgba(var(--veil-rgb), 0.6); padding: 0.32rem 0.6rem; border-radius: 999px;
  -webkit-backdrop-filter: blur(4px); backdrop-filter: blur(4px);
  -webkit-user-select: none; user-select: none;
}
.stage-label--held {
  color: var(--held-text); font-weight: 650;
  box-shadow: inset 0 0 0 1px rgba(var(--held-rgb), 0.7);
}
.stage-label--joint {
  position: relative; font-size: 0.8125rem; padding: 0.4rem 0.7rem 0.4rem 1.9rem; border-radius: 3px;
  background: rgba(var(--veil-rgb), 0.72);
  box-shadow: 0 0 0 1px rgba(var(--ivory-rgb), 0.12);
}
.stage-label--joint::before { /* leader line ending in a dot */
  content: ""; position: absolute; left: 0.5rem; top: 50%; width: 0.85rem; height: 1px;
  background: var(--ivory); opacity: 0.7;
}
.stage-label--joint::after {
  content: ""; position: absolute; left: 0.3rem; top: 50%; width: 5px; height: 5px; margin-top: -2.5px;
  border-radius: 50%; background: var(--noodle);
}
@media (max-width: 640px) {
  .stage-label { font-size: 0.6875rem; padding: 0.28rem 0.5rem; }
  .stage-label--joint { font-size: 0.72rem; padding-left: 1.7rem; }
}

/* 3D phase words pinned along the gripper's path (Approach ... Return). Layer is aria-hidden; the stage
   turns pointer events on in the sandbox only. Dark themes glow in the accent; light themes use ink. */
.stage-phase {
  white-space: nowrap; user-select: none; -webkit-user-select: none;
  font-family: "Archivo", system-ui, sans-serif; font-stretch: 112%; font-weight: 700;
  font-size: 1rem; line-height: 1; letter-spacing: 0; text-transform: none; font-variant-numeric: tabular-nums;
  color: var(--ivory);
  text-shadow: 0 0 10px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.7)), 0 1px 3px rgba(var(--veil-rgb), 0.9);
  transition: color 0.25s, text-shadow 0.25s, opacity 0.25s, transform 0.25s var(--ease-out);
}
.stage-phase--done { color: rgba(var(--ivory-rgb), 0.6); text-shadow: 0 1px 3px rgba(var(--veil-rgb), 0.8); }
.stage-phase--active {
  color: var(--accent-text);
  text-shadow: 0 0 16px rgba(var(--noodle-rgb), calc(var(--glow-a) + 0.25)), 0 0 34px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.7)), 0 1px 3px rgba(var(--veil-rgb), 0.9);
}
body[data-chapter="sandbox"] .stage-phase { cursor: pointer; }
body[data-chapter="sandbox"] .stage-phase:hover { color: var(--accent-text); }
html[data-mode="light"] .stage-phase { text-shadow: 0 0 8px rgba(var(--wall-rgb), 0.85), 0 0 2px rgba(var(--wall-rgb), 0.9); }
html[data-mode="light"] .stage-phase--done { color: rgba(var(--ivory-rgb), 0.72); }
html[data-mode="light"] .stage-phase--active { color: var(--ivory); text-shadow: 0 0 10px rgba(var(--noodle-rgb), 0.9), 0 0 3px rgba(var(--wall-rgb), 0.95); font-weight: 800; }
@media (max-width: 640px) { .stage-phase { font-size: 0.875rem; } }

/tactilevla/tactilevla-demo/css/telemetr:
/* Joint-state HUD: an instrument panel in glass, all colour from theme tokens */
.telemetry { pointer-events: none; }
.tm {
  padding: 0.7rem 0.9rem 0.8rem; border-radius: 0.9rem;
  background: rgba(var(--veil-rgb), 0.62);
  box-shadow: 0 0 0 1px var(--hair), 0 14px 40px -18px var(--shadow);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
  font-variant-numeric: tabular-nums; color: var(--ivory);
}
.tm-label { margin: 0 0 0.55rem; max-width: none !important; font-size: var(--fs-micro); line-height: 1.25; color: var(--caption); white-space: nowrap; }
.tm-cell { margin: 0 0 0.5rem; max-width: none !important; font-size: var(--fs-caption); font-weight: 650; color: var(--accent-text); min-height: 1.2em; }
.tm-rows { display: grid; gap: 0; }
.tm-rows li { display: grid; grid-template-columns: 6.6em 6.2ch; column-gap: 0.7rem; align-items: center; padding: 0.24rem 0; border-top: 1px solid var(--hair); font-size: 0.8125rem; line-height: 1.2; }
.tm-rows li:first-child { border-top: 0; }
.tm-name { color: var(--caption); white-space: nowrap; }
.tm-val { text-align: right; font-weight: 600; min-width: 6.2ch; white-space: nowrap; }
li[data-k="gripper"] .tm-val { min-width: 8ch; }

/* Gauges (full variant): zero-centred bars, filled toward the joint's side */
.telemetry--full .tm-rows li { grid-template-columns: 6.6em 8.4ch minmax(3.5rem, 1fr); }
.tm-gauge { position: relative; height: 0.3125rem; border-radius: 3px; background: rgba(var(--ivory-rgb), 0.12); overflow: hidden; }
.tm-gauge::after { content: ""; position: absolute; left: 50%; top: -1px; bottom: -1px; width: 1px; background: rgba(var(--ivory-rgb), 0.45); }
/* --a is signed (-1..1): scaleX flips the bar to the left of zero for negative angles */
.tm-gauge i { position: absolute; top: 0; bottom: 0; left: 50%; width: 50%; background: var(--noodle); border-radius: 3px; transform-origin: 0 50%; transform: scaleX(var(--a, 0)); }
.tm-gauge--one::after { display: none; }
.tm-gauge--one i { left: 0; width: 100%; background: var(--trained); }

/* Phase line: the pick-and-place in order, current step lit */
.tm-phase { display: flex; flex-wrap: wrap; gap: 0.15rem 0; margin-top: 0.7rem; padding-top: 0.6rem; border-top: 1px solid var(--hair); font-size: var(--fs-micro); }
.tm-phase li { color: var(--caption); opacity: 0.72; transition: color 0.2s, opacity 0.2s; }
.tm-phase li + li::before { content: "→"; margin: 0 0.4em; opacity: 0.5; }
.tm-phase li.is-on { color: var(--accent-text); opacity: 1; font-weight: 700; }

/* Placement */
.telemetry--hero { position: absolute; right: var(--gutter); bottom: 3.5rem; z-index: 2; width: 21rem; }
.telemetry--hero .tm { padding: 0.55rem 0.75rem 0.6rem; }
.telemetry--hero .tm-label { white-space: normal; font-size: 0.6875rem; }
.telemetry--hero .tm-rows { grid-template-columns: 1fr 1fr; column-gap: 1rem; }
.telemetry--hero .tm-rows li { font-size: var(--fs-micro); padding: 0.16rem 0; grid-template-columns: 1fr auto; column-gap: 0.4rem; }
.telemetry--hero .tm-rows li:nth-child(2) { border-top: 0; }
.telemetry--hero .tm-val { min-width: 0; }
.telemetry--compact { margin: 0 0 1.2rem; max-width: 24rem; pointer-events: auto; }
.telemetry--compact .tm-rows li { grid-template-columns: 1fr auto; }
.telemetry--compact .tm-rows { grid-template-columns: 1fr 1fr; column-gap: 1.2rem; }
.telemetry--compact .tm-rows li { grid-template-columns: 1fr auto; font-size: var(--fs-caption); }
.telemetry--compact .tm-rows li:nth-child(2) { border-top: 0; }
.telemetry--full { flex: 1; min-width: 0; pointer-events: auto; }
.telemetry--full .tm-label { white-space: normal; }

/* Sandbox row: picker left, panel right */
@media (max-width: 1100px) and (min-width: 821px) { .sandbox-row { flex-direction: column; } }
@media (max-width: 820px) {
  .telemetry--hero, .telemetry--compact { display: none; }   /* phones: sandbox only */
  .sandbox-row { flex-direction: column; gap: 0.8rem; }
  .telemetry--full .tm-rows li { grid-template-columns: 6.2em 8.4ch minmax(3rem, 1fr); font-size: var(--fs-caption); }
  .telemetry--full .tm-label { white-space: normal; }
}
.no-stage .telemetry, .is-loading .telemetry { display: none; }
@media (max-height: 760px) and (min-width: 821px) { .telemetry--hero { display: none; } }

/* ---- Round 7: phase buttons, timeline scrubber ---- */
.tm-phase { display: flex; flex-wrap: wrap; gap: 0.15rem 0; margin-top: 0.7rem; padding-top: 0.6rem; border-top: 1px solid var(--hair); font-size: var(--fs-micro); }
.tm-phase li { opacity: 1; color: inherit; transition: none; }
.tm-phase li + li::before { content: "→"; margin: 0 0.15em; opacity: 0.5; color: var(--caption); }
.tm-phase button { padding: 0.35rem 0.3rem; min-height: 1.75rem; border-radius: 0.4rem; font-size: inherit; color: var(--caption); opacity: 0.78; transition: color 0.2s, opacity 0.2s, background-color 0.2s; pointer-events: auto; }
.tm-phase button[aria-disabled="true"] { cursor: default; opacity: 0.5; }
.tm-phase button:not([aria-disabled="true"]):hover { background: rgba(var(--ivory-rgb), 0.1); color: var(--ivory); opacity: 1; }
.tm-phase button.is-on { color: var(--accent-text); opacity: 1; font-weight: 700; }

.tm-scrub { display: flex; align-items: center; gap: 0.5rem; margin-top: 0.5rem; pointer-events: auto; }
.tm-scrub[data-off="true"] { opacity: 0.5; }
.tm-play { flex: none; width: 2.75rem; height: 2.75rem; margin: -0.3rem 0 -0.3rem -0.55rem; display: grid; place-items: center; border-radius: 50%; }
.tm-play svg { width: 1.7rem; height: 1.7rem; padding: 0.4rem; border-radius: 50%; fill: var(--on-accent); background: var(--noodle); }
.tm-play[aria-disabled="true"] svg { background: rgba(var(--ivory-rgb), 0.25); fill: var(--ivory); }
.tm-play[aria-disabled="true"], .tm-track[aria-disabled="true"] { cursor: default; }
.tm-track { position: relative; flex: 1; height: 2.75rem; margin: -0.3rem 0; display: flex; align-items: center; cursor: pointer; touch-action: none; border-radius: 0.4rem; }
.tm-segs { position: relative; display: flex; gap: 2px; width: 100%; height: 0.5rem; }
.tm-segs span { flex-basis: 0; min-width: 4px; border-radius: 2px; background: rgba(var(--ivory-rgb), 0.16); transition: background-color 0.2s; }
.tm-segs span:nth-child(odd) { background: rgba(var(--ivory-rgb), 0.24); }
.tm-segs span.is-on { background: rgba(var(--noodle-rgb), 0.85); }
.tm-segs:empty::before { content: ""; flex: 1; background: rgba(var(--ivory-rgb), 0.16); border-radius: 2px; }
.tm-head { position: absolute; top: 50%; left: 0; width: 0.8rem; height: 0.8rem; margin: -0.4rem 0 0 -0.4rem; border-radius: 50%; background: var(--ivory); box-shadow: 0 0 0 2px rgba(var(--veil-rgb), 0.9), 0 0 14px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.9)); pointer-events: none; }
.tm-track[aria-disabled="true"] .tm-head { opacity: 0.4; }
.tm-track:focus-visible { outline: 2px solid var(--noodle); outline-offset: 2px; }

/* Phones: the sandbox HUD is compact — two columns, no gauges — with the phase line and scrubber under it */
@media (max-width: 820px) {
  .telemetry--full .tm { padding: 0.55rem 0.7rem 0.6rem; }
  .telemetry--full .tm-label { font-size: 0.6875rem; margin-bottom: 0.35rem; }
  .telemetry--full .tm-cell { margin-bottom: 0.3rem; }
  .telemetry--full .tm-rows { grid-template-columns: 1fr 1fr; column-gap: 0.9rem; }
  .telemetry--full .tm-rows li { grid-template-columns: 1fr auto; font-size: var(--fs-micro); padding: 0.16rem 0; }
  .telemetry--full .tm-rows li:nth-child(2) { border-top: 0; }
  .telemetry--full .tm-val { min-width: 0; }
  .telemetry--full .tm-gauge { display: none; }
  .telemetry--full .tm-phase { margin-top: 0.4rem; padding-top: 0.35rem; }
  .telemetry--full .tm-phase button { padding: 0.35rem 0.15rem; }
}

/tactilevla/tactilevla-demo/css/theme.cs:
/* Palette-aware finish: luminous type moments, richer buttons and chips, grain, the review switcher.
   Everything here reads tokens (see css/tokens.css and js/ui/theme.js), so it re-tints with the theme.
   Restraint: one luminous moment per screen. */

/* Film grain tied to the theme (a static tile, no blend mode, so it costs nothing per frame) */
.grain {
  position: fixed; inset: 0; z-index: 0; pointer-events: none; opacity: var(--grain-a);
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='.33 .33 .33 0 0 .33 .33 .33 0 0 .33 .33 .33 0 0 0 0 0 0 1'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
  background-size: 220px 220px;
}
@media (prefers-reduced-motion: reduce) { .grain { opacity: calc(var(--grain-a) * 0.6); } }

/* Buttons: a lit primary, a crisp secondary */
.btn--primary {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.34), rgba(255, 255, 255, 0) 55%), var(--noodle);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5), inset 0 -1px 0 rgba(0, 0, 0, 0.14),
    0 10px 34px -10px rgba(var(--noodle-rgb), calc(var(--glow-a) + 0.2));
}
.btn--ghost { background: rgba(var(--ivory-rgb), 0.04); box-shadow: inset 0 0 0 1px rgba(var(--ivory-rgb), 0.5); }
.btn--ghost:hover { background: rgba(var(--ivory-rgb), 0.1); box-shadow: inset 0 0 0 1px var(--ivory); }
.seg-btn[aria-pressed="true"] {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.3), rgba(255, 255, 255, 0) 55%), var(--noodle);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.45), 0 6px 22px -8px rgba(var(--noodle-rgb), calc(var(--glow-a) + 0.15));
}

/* Arm: the one luminous moment is the cost stat */
.stat-n {
  background: linear-gradient(100deg, var(--noodle) 15%, var(--held) 95%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: transparent;
  filter: drop-shadow(0 0 30px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.7)));
}

/* Data: the counter carries the accent; its rule and the stat hairlines pick it up */
.counter-n { color: var(--accent-text); text-shadow: 0 0 34px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.7)); }
.counter { border-top: 1px solid transparent; border-image: linear-gradient(90deg, rgba(var(--noodle-rgb), 0.75), rgba(var(--ivory-rgb), 0.12) 70%) 1; }
.stats > div { border-left-color: rgba(var(--noodle-rgb), 0.5); }
.closing { color: var(--held-text); text-shadow: 0 0 44px rgba(var(--held-rgb), calc(var(--glow-a) * 0.8)); }

/* Test: B2 in the held-out colour, lit from above */
.giant-cell {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.4), rgba(255, 255, 255, 0) 32%),
    linear-gradient(180deg, var(--held) 34%, rgba(var(--held-rgb), 0.42));
  -webkit-background-clip: text; background-clip: text;
  filter: drop-shadow(0 0 38px rgba(var(--held-rgb), calc(var(--glow-a) * 0.75)));
}

/* Results: numerals wash from ink to the accent; filled trials glow softly */
.results-title {
  background: linear-gradient(180deg, var(--ivory) 30%, var(--accent-text) 140%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: transparent;
  filter: drop-shadow(0 0 32px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.35)));
}
.row-score .num { color: var(--accent-text); }
.dot.is-hit { box-shadow: 0 0 12px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.9)); }
.range { background: linear-gradient(90deg, rgba(var(--noodle-rgb), 0.55), rgba(var(--noodle-rgb), 0.85)); }

/* Film: saturated chips */
.tag--held { background: rgba(var(--held-rgb), 0.18); box-shadow: inset 0 0 0 1px var(--held); }
.tag--trained { background: rgba(var(--trained-rgb), 0.18); box-shadow: inset 0 0 0 1px rgba(var(--trained-rgb), 0.9); }

/* Touch: the peak bar burns brighter; the roadmap lights its done and next steps */
.bars li[style*="--v:152"] .b-bar i { background: linear-gradient(90deg, var(--noodle), var(--held)); box-shadow: 0 0 16px rgba(var(--noodle-rgb), calc(var(--glow-a) * 0.7)); }
.roadmap .is-done::before { box-shadow: 0 0 10px rgba(var(--trained-rgb), 0.75); }
.roadmap .is-next { border-top-color: rgba(var(--noodle-rgb), 0.6); }
.roadmap .is-next .ph-t { font-weight: 600; }
.roadmap .is-next::before { box-shadow: 0 0 0 4px rgba(var(--noodle-rgb), 0.22), 0 0 16px rgba(var(--noodle-rgb), 0.6); }

/* Sandbox tiles glow on hover */
.cell-btn:hover:not([aria-disabled="true"]) { box-shadow: inset 0 0 0 1px rgba(var(--trained-rgb), 0.9), 0 0 20px -4px rgba(var(--trained-rgb), 0.55); }
.cell-btn--held:hover:not([aria-disabled="true"]) { box-shadow: inset 0 0 0 1px var(--held), 0 0 20px -4px rgba(var(--held-rgb), 0.6); }

/* Progress rail: accent gradient with a faint glow; ticks in the accent */
.rail i { background: linear-gradient(to bottom, var(--noodle), var(--held)); box-shadow: 0 0 10px rgba(var(--noodle-rgb), 0.55); opacity: 1; }
.rail b { background: rgba(var(--noodle-rgb), 0.55); }
.strip-progress i { background: linear-gradient(90deg, var(--noodle), var(--held)); }

/* Review switcher (?themes) */
.theme-switcher {
  position: fixed; left: var(--gutter); bottom: calc(env(safe-area-inset-bottom, 0px) + 3.6rem); z-index: 40;
  display: flex; gap: 0.25rem; padding: 0.3rem; border-radius: 999px;
  background: rgba(var(--veil-rgb), 0.82); box-shadow: 0 0 0 1px var(--hair-strong), 0 12px 32px -12px var(--shadow);
  -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
}
.theme-switcher button { display: flex; align-items: center; gap: 0.45rem; min-height: 2.25rem; padding: 0 0.8rem 0 0.4rem; border-radius: 999px; font-size: var(--fs-micro); color: var(--ivory); }
.theme-switcher button[aria-pressed="true"] { background: rgba(var(--ivory-rgb), 0.14); box-shadow: inset 0 0 0 1px var(--hair-strong); }
.theme-switcher i { width: 1.25rem; height: 1.25rem; border-radius: 50%; box-shadow: 0 0 0 1px rgba(var(--ivory-rgb), 0.35); }
@media (max-width: 820px) { .theme-switcher { left: 0.5rem; right: 0.5rem; justify-content: space-between; bottom: calc(env(safe-area-inset-bottom, 0px) + 0.5rem); } .theme-switcher button { padding-right: 0.55rem; } }

/* Gradient-clipped type has a transparent fill: the inherited panel text-shadow would show through it and muddy the colour */
.stat-n, .results-title, .giant-cell, .results-title span { text-shadow: none; }
.results-title { background: linear-gradient(180deg, var(--ivory) 0%, var(--ivory) 30%, var(--accent-text) 125%); -webkit-background-clip: text; background-clip: text; }

/tactilevla/tactilevla-demo/css/tokens.c:
:root {
  --wall: #0c1626;
  --wall-2: #060b15;
  --ivory: #f4ecd8;
  --dim: #a3b3c6;
  --noodle: #ffc93c;
  --trained: #2fe0c2;
  --held: #ff7a1a;

  /* Derived tokens. js/ui/theme.js recomputes these for the active theme; these are the nocturne defaults
     so the page is right before (or without) JS. `--*-rgb` are bare "r, g, b" for use in rgba(). */
  --wall-rgb: 12, 22, 38; --wall-2-rgb: 6, 11, 21; --ivory-rgb: 244, 236, 216; --dim-rgb: 163, 179, 198;
  --noodle-rgb: 255, 201, 60; --trained-rgb: 47, 224, 194; --held-rgb: 255, 122, 26;
  --veil-rgb: 6, 11, 21;            /* scrims, pills, panel veils: the page background, whatever its hue */
  --shadow-rgb: 0, 0, 0; --shadow-a: 0.9; --shadow: rgba(var(--shadow-rgb), var(--shadow-a));
  --on-accent: #060b15;              /* text on --noodle fills */
  --accent-text: #ffc93c; --held-text: #ff7a1a; --trained-text: #2fe0c2;   /* accents safe to use as text */
  --ring-color: #ffc27a; --ring-rgb: 255, 194, 122;
  --glow-a: 0.5; --grain-a: 0.055;
  --hair: rgba(var(--ivory-rgb), 0.16);
  --hair-strong: rgba(var(--ivory-rgb), 0.34);
  --caption: rgba(var(--ivory-rgb), 0.74);
  --seg-idle: rgba(var(--ivory-rgb), 0.78);
  --media-ink: #f3ead6;              /* icons and labels drawn over video, which is always dark */

  --gutter: clamp(16px, 6.5vw, 8rem);
  --col: min(34rem, 41vw);
  --wide: min(42rem, 41vw);
  --topbar-h: 4.25rem;
  --space-section: clamp(4rem, 8vw, 6rem);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-io: cubic-bezier(0.65, 0, 0.35, 1);

  --fs-body: 1.0625rem;
  --fs-h2: clamp(2rem, 3.5vw, 3.35rem);
  --fs-small: 0.9375rem;
  --fs-caption: 0.8125rem;
  --fs-micro: 0.75rem;
}

/tactilevla/tactilevla-demo/css/touch-sa:
/* ---- Touch ---- */
.bars { margin: 1.8rem 0; }
.bars figcaption { color: var(--ivory); font-weight: 600; font-size: 0.9375rem; margin-bottom: 1rem; }
.bars li { display: grid; grid-template-columns: 7.2rem 1fr 3ch; align-items: center; gap: 0.9rem; padding: 0.42rem 0; }
.b-name { font-size: 0.9375rem; color: var(--ivory); }
.b-bar { display: block; height: 0.75rem; background: rgba(var(--ivory-rgb), 0.07); border-radius: 2px; overflow: hidden; }
.b-bar i { display: block; height: 100%; width: calc(var(--v) / 160 * 100%); background: var(--ivory); opacity: 0.86; transform-origin: 0 50%; transform: scaleX(var(--grow, 1)); }
.bars li[style*="--v:152"] .b-bar i { background: var(--noodle); opacity: 1; }
.b-val { text-align: right; font-weight: 650; font-size: 0.9375rem; }
.bars-note { margin-top: 0.9rem; max-width: 34rem; }
.roadmap { margin-top: 2rem; position: relative; }
.roadmap li { display: grid; grid-template-columns: 5.6rem 1fr auto; gap: 0.2rem 1rem; align-items: baseline; padding: 0.85rem 0 0.85rem 1.5rem; border-top: 1px solid var(--hair); position: relative; }
.roadmap li:last-child { border-bottom: 1px solid var(--hair); }
.roadmap li::before { content: ""; position: absolute; left: 0; top: 1.35rem; width: 0.55rem; height: 0.55rem; border-radius: 50%; box-shadow: inset 0 0 0 1.5px var(--dim); }
.roadmap .is-done::before { background: var(--trained); box-shadow: none; }
.roadmap .is-next::before { background: var(--noodle); box-shadow: 0 0 0 4px rgba(var(--noodle-rgb), 0.2); }
.ph { font-weight: 700; font-stretch: 112%; font-variant-numeric: tabular-nums; }
.ph-t { color: var(--ivory); }
.ph-s { font-size: var(--fs-caption); color: var(--dim); }
.is-done .ph-s { color: var(--trained-text); }
.is-next .ph-s { color: var(--accent-text); font-weight: 650; }
.is-next .ph { color: var(--accent-text); }
@media (max-width: 520px) {
  .bars li { grid-template-columns: 6.2rem 1fr 3ch; gap: 0.6rem; }
  .roadmap li { grid-template-columns: 1fr auto; }
  .ph-t { grid-column: 1 / -1; grid-row: 2; }
}

/* ---- Sandbox ---- */
.sandbox-row { display: flex; align-items: flex-start; gap: 1.5rem; margin: 1.6rem 0 0.9rem; }
.picker-wrap { flex: none; }
.picker-arm { text-align: center; font-size: var(--fs-micro); color: var(--dim); margin: 0 0 0.5rem; max-width: none !important; padding-bottom: 0.4rem; border-bottom: 1px solid var(--hair); margin-bottom: 0.6rem; }
.picker { display: grid; grid-template-columns: repeat(3, 4.5rem); gap: 0.5rem; }
.cell-btn {
  aspect-ratio: 1; display: grid; place-items: center; border-radius: 4px; font-stretch: 100%; font-weight: 700; font-size: 1.05rem;
  color: var(--ivory); background: linear-gradient(rgba(var(--trained-rgb), 0.18), rgba(var(--trained-rgb), 0.18)), rgba(var(--veil-rgb), 0.85); box-shadow: inset 0 0 0 1px rgba(var(--trained-rgb), 0.6);
  font-variant-numeric: tabular-nums; transition: background-color 0.25s, transform 0.25s var(--ease-out), opacity 0.25s;
}
.cell-btn:hover:not([aria-disabled="true"]) { background: linear-gradient(rgba(var(--trained-rgb), 0.34), rgba(var(--trained-rgb), 0.34)), rgba(var(--veil-rgb), 0.85); transform: translateY(-2px); }
.cell-btn--held { color: var(--held-text); background: linear-gradient(rgba(var(--held-rgb), 0.18), rgba(var(--held-rgb), 0.18)), rgba(var(--veil-rgb), 0.88); box-shadow: inset 0 0 0 1px var(--held); }
.cell-btn--held:hover:not([aria-disabled="true"]) { background: linear-gradient(rgba(var(--held-rgb), 0.34), rgba(var(--held-rgb), 0.34)), rgba(var(--veil-rgb), 0.88); }
.cell-btn.is-running { background: var(--noodle); color: var(--on-accent); box-shadow: none; }
.cell-btn[aria-disabled="true"] { cursor: progress; opacity: 0.45; }
.cell-btn.is-running[aria-disabled="true"] { opacity: 1; }
.no-webgl .cell-btn[aria-disabled="true"] { cursor: not-allowed; }
.picker-status { min-height: 1.6em; color: var(--ivory); font-weight: 600; font-variant-numeric: tabular-nums; }
.save-btn { margin-top: 1rem; min-height: 2.75rem; }
.disclaimer {
  margin-top: 1.4rem; padding: 0.15rem 0 0.15rem 1.1rem; border-left: 3px solid var(--noodle);
  font-size: 1rem; line-height: 1.55; color: var(--ivory);
}

/* ---- Limits + footer: a light veil with blur so the 3D stays alive behind ---- */
.chapter--limits { display: block; padding-bottom: 0; isolation: isolate; }
.chapter--limits::before { /* blur + veil live behind the text column only; the right stays crisp for the final shot */
  content: ""; position: absolute; inset: 0 auto 0 0; width: 62%; z-index: -1; pointer-events: none;
  background: rgba(var(--veil-rgb), 0.55); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 12rem), linear-gradient(to right, #000 55%, transparent);
  -webkit-mask-composite: source-in;
  mask-image: linear-gradient(to bottom, transparent, #000 12rem), linear-gradient(to right, #000 55%, transparent);
  mask-composite: intersect;
}
.chapter--limits > .panel { margin-top: 4rem; }
.limits li { padding: 1rem 0; border-top: 1px solid var(--hair); }
.limits li:last-child { border-bottom: 1px solid var(--hair); }
.footer {
  position: relative; z-index: 1; margin: 0; padding: 3rem var(--gutter) 3.5rem;
  font-size: 0.875rem; color: var(--dim); display: grid; gap: 0.35rem;
}
.footer::before { /* continues the limits veil: same feathered column, so the seam disappears */
  content: ""; position: absolute; inset: 0 auto 0 0; width: 62%; z-index: -1; pointer-events: none;
  background: rgba(var(--veil-rgb), 0.55); -webkit-backdrop-filter: blur(14px); backdrop-filter: blur(14px);
  -webkit-mask-image: linear-gradient(to right, #000 55%, transparent); mask-image: linear-gradient(to right, #000 55%, transparent);
}
.footer p { margin: 0; }
.footer-name { color: var(--ivory); font-stretch: 100%; font-weight: 700; font-size: 1.125rem; margin-bottom: 0.4rem !important; }
.footer a { color: var(--ivory); }
@media (max-width: 820px) {
