    wedgeEdges.material.color.copy(PAL.held).multiplyScalar(mixL(2.6, 1.0))
  }
  let lightSeen = null
  return {
    group,
    update(weight, tcp) {
      group.visible = weight > 0.01
      wrist.visible = group.visible
      if (!group.visible) return
      if (painted !== PAL.stamp) repaint()
