  root.visible = false
  const mk = (linewidth) => new LineMaterial({ linewidth, transparent: true, depthWrite: false, depthTest: true, worldUnits: false, toneMapped: false })
  const trackMat = mk(2)
  const arcMat = mk(4)
  const tickMat = mk(5)
