        tb[3] = r * 1.3 * c; tb[4] = r * 1.3 * s; tb[5] = 0
        it.tick.buf.needsUpdate = true
      }
    },
    dispose() {
      for (const it of items) { it.frame.removeFromParent(); it.side.traverse((o) => o.geometry?.dispose?.()) }
      for (const m of mats) m.dispose()
      root.removeFromParent()
    },
  }
}

