  // ---- WebGL parts ----
  const group = new THREE.Group()
  group.visible = false
  scene.add(group)
  const leadMat = new LineMaterial({ linewidth: 0.9, transparent: true, depthWrite: false, depthTest: true, toneMapped: false, vertexColors: true })
