  const words = PHASE_NAMES.map((ph, i) => {
    const el = document.createElement('div')
    el.className = 'stage-phase'
    el.dataset.phase = ph
    const label = document.createElement('span')
    label.textContent = LABELS[ph]
    const bar = document.createElement('i')
