      ph, el, bar, obj, cls: '', w: 0, h: 0, pw: 0, ph_: 0,
      a: 0, av: 0, k: 0, kv: 0, s: 1, // opacity, active amount (0..1) - both spring-smoothed
      px: null, py: null, vx: 0, vy: 0, slot: -1, slotT: -9, // on-screen centre (spring) and the chosen layout slot
