  function setPlan(plan) {
    state.plan = plan
    state.master = 0 // words fade in for the new task
    state.headA = 0
    for (const w of words) { w.a = 0; w.av = 0; w.k = 0; w.kv = 0; w.s = 1; w.px = null; w.slot = -1; w.slotT = -9; w.lastK = -1; w.lastBar = -1 }
