    flashFail(point) { st.failP = point; st.failT = 0 },
    setEnabled(on) { st.enabled = on },
    /** true while a plan is being solved or a failure flash is showing */
    get busy() { return !!st.planning || st.failT < 1 },
    update(dt) {
      st.time += dt
      const light = isLightPal()
      const blend = light ? THREE.NormalBlending : THREE.AdditiveBlending
      const gain = light ? 1 : 1.8
      for (const r of [hover, plan, fail]) if (r.m.blending !== blend) { r.m.blending = blend; r.m.needsUpdate = true }

      // hover cursor: follows the pointer with a little lag, colour by reach test
      const showHover = st.enabled && !!st.hoverP && !st.planning
      st.hoverA += ((showHover ? 1 : 0) - st.hoverA) * (1 - Math.exp(-dt * 14))
      if (st.hoverP) {
        const k = 1 - Math.exp(-dt * 22)
        if (st.hx === 0 && st.hz === 0) { st.hx = st.hoverP.x; st.hz = st.hoverP.z }
        st.hx += (st.hoverP.x - st.hx) * k; st.hz += (st.hoverP.z - st.hz) * k
      }
      hover.o.visible = st.hoverA > 0.01
      if (hover.o.visible) {
        hover.o.position.set(st.hx, TABLE_Y + 0.0025, st.hz)
        hover.m.color.copy(st.hoverOk ? PAL.trained : RED).multiplyScalar(gain)
        hover.m.opacity = st.hoverA * (st.hoverOk ? 0.85 : 0.6)
        const r = 0.03 + (st.hoverOk ? 0 : 0.004 * Math.sin(st.time * 8))
        hover.o.scale.set(r, 1, r)
      }
      // planning pulse
      st.planA += ((st.planning ? 1 : 0) - st.planA) * (1 - Math.exp(-dt * 16))
      plan.o.visible = st.planA > 0.01 && !!(st.planning || st.planA > 0.02)
      if (st.planning) plan.o.position.set(st.planning.x, TABLE_Y + 0.0026, st.planning.z)
      if (plan.o.visible) {
        const u = (st.time * 2.2) % 1
        const r = 0.02 + 0.03 * u
        plan.o.scale.set(r, 1, r)
        plan.m.color.copy(PAL.accent).multiplyScalar(gain)
        plan.m.opacity = st.planA * (1 - u) * 0.9
      }
      // out-of-reach flash: a red ring that blooms once, and the label
      if (st.failT < 1) {
        st.failT = Math.min(1, st.failT + dt / 1.5)
        const u = st.failT
        const p = st.failP
        fail.o.visible = true
        fail.o.position.set(p.x, TABLE_Y + 0.0027, p.z)
        const r = 0.02 + 0.05 * (1 - Math.pow(1 - Math.min(1, u * 2.2), 3))
        fail.o.scale.set(r, 1, r)
        fail.m.color.copy(RED).multiplyScalar(gain)
        fail.m.opacity = Math.max(0, 1 - Math.max(0, (u - 0.25) / 0.75))
        label.position.set(p.x + 0.078, 0.012, p.z)
        const la = Math.min(1, u * 8) * Math.max(0, 1 - Math.max(0, (u - 0.6) / 0.4))
        el.style.opacity = la.toFixed(2)
        el.style.visibility = la > 0.01 ? 'visible' : 'hidden'
        if (u >= 1) { fail.o.visible = false; el.style.visibility = 'hidden' }
      }
      group.visible = hover.o.visible || plan.o.visible || fail.o.visible
    },
    dispose() { geo.dispose(); for (const r of [hover, plan, fail]) r.m.dispose(); wrap.remove(); group.removeFromParent() },
  }
}

// Motion plans: baked joint-space waypoints (plans.json) loaded at boot, with live IK as the fallback.
// Regenerate with js/stage/tools/bake.html whenever layout.js or the choreography in tasks.js changes.
import * as THREE from 'three'
import { CELLS } from './protocol.js'
import { GRID, CUP, NOODLE, cellCenter, noodleYaw } from './layout.js'
import { solveTask, PLAN_VERSION } from './tasks.js'

export const HOME_TARGET = [0.19, 0.17, 0]
const PLANS_URL = new URL('./plans.json', import.meta.url).href

/** FNV-1a over everything the solved waypoints depend on. */
export function layoutHash(grasp) {
  const r = (v) => Math.round(v * 1e5) / 1e5
  const src = JSON.stringify({
    v: PLAN_VERSION, GRID, CUP, NOODLE, HOME_TARGET, grasp: grasp ? [...grasp.local.map(r), r(grasp.theta)] : null,
    cells: CELLS.map((c) => [...cellCenter(c).toArray().map(r), r(noodleYaw(c))]),
  })
  let h = 0x811c9dc5
  for (let i = 0; i < src.length; i++) { h ^= src.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0 }
  return h.toString(16)
}

export function solveHome(ik) {
  const s = ik.solve(new THREE.Vector3(...HOME_TARGET), { maxTilt: 1.0, weights: [0.1, 0.04, 0.015] })
  return [...s.q, 0, 0.35].map((v) => Math.round(v * 1e4) / 1e4)
}

/** Everything IK produces, as plain JSON-able data. */
export async function solveAll(ik, onProgress = () => {}) {
  const idle = () => new Promise((r) => setTimeout(r, 0))
  const homeQ = solveHome(ik)
  const specs = {}
  const order = ['B2', 'A2', ...CELLS.filter((c) => c !== 'B2' && c !== 'A2')]
  for (let i = 0; i < order.length; i++) {
    specs[order[i]] = solveTask(ik, homeQ, order[i])
    onProgress((i + 1) / order.length)
    await idle() // keep the loader ring animating
  }
  return { hash: layoutHash(ik.rig.grasp), homeQ, specs }
}

/** @returns {Promise<{homeQ:number[], specs:Record<string,any>, source:'baked'|'live'}>} */
export async function loadPlans(ik, onProgress = () => {}) {
  try {
    const res = await fetch(PLANS_URL)
    if (res.ok) {
      const data = await res.json()
      if (data.hash === layoutHash(ik.rig.grasp) && CELLS.every((c) => data.specs?.[c]?.knots?.length)) {
        return { homeQ: data.homeQ, specs: data.specs, source: 'baked' }
      }
    }
  } catch { /* fall through to live IK */ }
  console.info('stage: baked plans missing or stale, solving IK live (run js/stage/tools/bake.html to regenerate)')
  const live = await solveAll(ik, onProgress)
  return { homeQ: live.homeQ, specs: live.specs, source: 'live' }
}

