// Noodle (foam tube) and the yellow scalloped cup. (The table lives in ground.js.)
import * as THREE from 'three'
import { NOODLE, CUP, TABLE_Y, cellCenter, noodleYaw } from './layout.js'
import { fallPose } from './tasks.js'

function foamBump() {
  const c = document.createElement('canvas')
  c.width = c.height = 128
  const g = c.getContext('2d')
  const img = g.createImageData(128, 128)
  for (let i = 0; i < img.data.length; i += 4) {
    const v = 128 + (Math.random() - 0.5) * 120
    img.data[i] = img.data[i + 1] = img.data[i + 2] = v
    img.data[i + 3] = 255
  }
  g.putImageData(img, 0, 0)
  const t = new THREE.CanvasTexture(c)
  t.wrapS = t.wrapT = THREE.RepeatWrapping
  t.repeat.set(3, 3)
  return t
}

export function buildNoodleMesh() {
  const s = new THREE.Shape()
  s.absarc(0, 0, NOODLE.r, 0, Math.PI * 2, false)
  const hole = new THREE.Path()
  hole.absarc(0, 0, NOODLE.hole, 0, Math.PI * 2, true)
  s.holes.push(hole)
  const geo = new THREE.ExtrudeGeometry(s, {
    depth: NOODLE.len - 0.0024, curveSegments: 40, bevelEnabled: true,
    bevelThickness: 0.0012, bevelSize: 0.0012, bevelSegments: 2,
  })
  geo.translate(0, 0, -(NOODLE.len - 0.0024) / 2)
  geo.rotateY(Math.PI / 2) // tube axis -> local X
  geo.computeVertexNormals()
  const bump = foamBump()
  const mat = new THREE.MeshPhysicalMaterial({
    color: 0xf4c430, roughness: 0.86, metalness: 0, specularIntensity: 0.35, bumpMap: bump, bumpScale: 0.35,
    emissive: new THREE.Color(0xf4c430), emissiveIntensity: 0.05,
  })
  const mesh = new THREE.Mesh(geo, mat)
  mesh.castShadow = true
  mesh.receiveShadow = true
  return mesh
}

export function buildCupMesh() {
  const N = 160
  const prof = []
  const h = CUP.h
  const th = CUP.wall
  const outer = (t) => new THREE.Vector2(CUP.baseR + (CUP.rimR - CUP.baseR) * Math.pow(t, 0.75), h * t)
  // inner bottom centre -> inner wall up -> rim -> outer wall down -> outer bottom centre
  prof.push(new THREE.Vector2(0, th))
  prof.push(new THREE.Vector2(CUP.baseR - th * 2, th))
  for (let i = 0; i <= 14; i++) {
    const t = i / 14
    const p = outer(t)
    prof.push(new THREE.Vector2(p.x - th * (1.2 - 0.2 * t), p.y + th * 0.4))
  }
  for (let i = 0; i <= 3; i++) { // rounded rim
    const a = (i / 3) * Math.PI
    const c = outer(1)
    prof.push(new THREE.Vector2(c.x - th * 0.6 + Math.cos(Math.PI - a) * th * -0.6, c.y + Math.sin(a) * th * 0.8))
  }
  for (let i = 14; i >= 0; i--) {
    const t = i / 14
    prof.push(outer(t))
  }
  prof.push(new THREE.Vector2(0, 0))
  const geo = new THREE.LatheGeometry(prof, N)
  const pos = geo.attributes.position
  const P = prof.length
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i)
    const r = Math.hypot(x, z)
    if (r < 1e-6) continue
    const th2 = Math.atan2(z, x)
    const t = Math.min(1, Math.max(0, y / h))
    const amp = 0.09 * Math.pow(t, 1.3) + 0.012
    const k = 1 + amp * Math.cos(8 * th2)
    pos.setXYZ(i, x * k, y, z * k)
  }
  geo.computeVertexNormals()
  // fix seam normals (lathe duplicates the first/last column)
  const n = geo.attributes.normal
  for (let j = 0; j < P; j++) {
    const a = j, b = N * P + j
    const nx = n.getX(a) + n.getX(b), ny = n.getY(a) + n.getY(b), nz = n.getZ(a) + n.getZ(b)
    const l = Math.hypot(nx, ny, nz) || 1
    n.setXYZ(a, nx / l, ny / l, nz / l)
    n.setXYZ(b, nx / l, ny / l, nz / l)
  }
  const mat = new THREE.MeshPhysicalMaterial({
    color: 0xf3d020, roughness: 0.42, metalness: 0, clearcoat: 0.45, clearcoatRoughness: 0.35, specularIntensity: 0.6,
    side: THREE.DoubleSide,
  })
  const mesh = new THREE.Mesh(geo, mat)
  mesh.castShadow = true
  mesh.receiveShadow = true
  mesh.position.set(CUP.x, TABLE_Y, CUP.z)
  return mesh
}

const smooth = (t) => t * t * (3 - 2 * t)

/** The noodle with a tiny state machine: table / held / falling / cup / hidden. */
export class Noodle {
  constructor(scene, tcp) {
    this.scene = scene
    this.tcp = tcp
    this.mesh = buildNoodleMesh()
    this.mesh.visible = false
    scene.add(this.mesh)
    this.state = 'hidden'
    this.cell = null
    this.scaleT = 1 // 0..1 pop-in
    this.scaleDir = 0
    this.vel = new THREE.Vector3()
    this.spin = new THREE.Quaternion()
    this.cupBottomY = TABLE_Y + CUP.wall + NOODLE.r
    this._q = new THREE.Quaternion()
    this._v = new THREE.Vector3()
    this.bounces = 0
    this.ghost = new THREE.Mesh(this.mesh.geometry, this.mesh.material)
    this.ghost.castShadow = true
    this.ghost.visible = false
    this.ghostT = 0
    scene.add(this.ghost)
  }

  /** Pop the noodle in at a cell on the table. */
  spawnAt(cell, animate = true) {
    if (this.state === 'cup' && animate) { // the previous noodle shrinks away out of the cup
      this.ghost.position.copy(this.mesh.position)
      this.ghost.quaternion.copy(this.mesh.quaternion)
      this.ghost.visible = true
      this.ghostT = 1
    }
    this.scene.attach(this.mesh)
    this.mesh.visible = true
    const c = cellCenter(cell)
    this.mesh.position.set(c.x, TABLE_Y + NOODLE.r, c.z)
    this.mesh.quaternion.setFromAxisAngle(new THREE.Vector3(0, 1, 0), -noodleYaw(cell))
    this.state = 'table'
    this.cell = cell
    this.scaleT = animate ? 0 : 1
    this.scaleDir = animate ? 1 : 0
    this.mesh.scale.setScalar(animate ? 0.001 : 1)
  }

  /** Attach to the gripper at its current world transform (called at the grasp instant). */
  grab() {
    this.tcp.attach(this.mesh)
    this.state = 'held'
  }

  /** Place the noodle directly in the gripper using a precomputed tcp-frame transform. */
  holdLocal(local) {
    this.tcp.add(this.mesh)
    this.mesh.position.copy(local.p)
    this.mesh.quaternion.copy(local.q)
    this.mesh.visible = true
    this.state = 'held'
    this.cell = null
    this.scaleT = 0
    this.scaleDir = 1
    this.mesh.scale.setScalar(0.001)
  }

  /**
   * A new task is starting: the previous noodle (sitting in the cup) shrinks away, and the pose is then owned by
   * applyPlan() every frame.
   */
  beginTask(plan) {
    if (this.state === 'cup' && this.mesh.visible) {
      this.ghost.position.copy(this.mesh.position)
      this.ghost.quaternion.copy(this.mesh.quaternion)
      this.ghost.visible = true
      this.ghostT = 1
    }
    this.cell = plan.cell
  }

  /**
   * The noodle at task time t, as a pure function of the plan: on the table until the jaws close, carried in the gripper
   * until they open, then the closed-form drop into the cup. Scrubbing forwards or backwards is therefore always
   * consistent. `popIn` grows it from nothing over the first 0.4 s (live playback only).
   */
  applyPlan(plan, t, popIn = false) {
    const m = this.mesh
    m.visible = true
    this.scaleDir = 0
    this.cell = plan.cell
    if (t < plan.grabT) {
      if (m.parent !== this.scene) this.scene.add(m)
      m.position.copy(plan.tablePose.p)
      m.quaternion.copy(plan.tablePose.q)
      m.scale.setScalar(popIn ? Math.max(0.001, smooth(Math.min(1, t / 0.4))) : 1)
      this.state = 'table'
    } else if (t < plan.releaseT) {
      if (m.parent !== this.tcp) this.tcp.add(m)
      m.position.copy(plan.heldLocal.p)
      m.quaternion.copy(plan.heldLocal.q)
      m.scale.setScalar(1)
      this.state = 'held'
    } else {
      if (m.parent !== this.scene) this.scene.add(m)
      const tau = t - plan.releaseT
      fallPose(plan.fall, tau, m.position, m.quaternion)
      m.scale.setScalar(1)
      this.state = tau >= plan.fall.end ? 'cup' : 'falling'
    }
  }

  hide(animate = true) {
    if (this.state === 'hidden') return
    if (animate) { this.scaleDir = -1; this.scaleT = Math.min(this.scaleT, 1) } else { this.mesh.visible = false; this.state = 'hidden' }
  }

  update(dt) {
    const m = this.mesh
    if (this.ghost.visible) {
      this.ghostT = Math.max(0, this.ghostT - dt / 0.45)
      this.ghost.scale.setScalar(Math.max(0.001, smooth(this.ghostT)))
      if (this.ghostT <= 0) this.ghost.visible = false
    }
    if (this.scaleDir !== 0) {
      this.scaleT = THREE.MathUtils.clamp(this.scaleT + this.scaleDir * dt / 0.4, 0, 1)
      const s = Math.max(0.001, smooth(this.scaleT))
      m.scale.setScalar(this.state === 'hidden' ? 1 : s)
      if (this.scaleDir > 0 && this.scaleT >= 1) this.scaleDir = 0
      if (this.scaleDir < 0 && this.scaleT <= 0) { this.scaleDir = 0; m.visible = false; this.state = 'hidden'; this.scene.attach(m) }
    }
  }
}

// Recording protocol shared with the page: pure functions, no DOM, no three.js.
export const CELLS = ['A1', 'A2', 'A3', 'B1', 'B2', 'B3', 'C1', 'C2', 'C3']
export const HELD_OUT = 'B2'
export const PERIMETER = ['A1', 'B1', 'C1', 'C2', 'C3', 'B3', 'A3', 'A2']
export const TOTAL_EPISODES = 160
// The data chapter's scrub fills all 160 episodes by this fraction of the pin, then holds the complete picture.
// Stage and page both map count = episodeAt(min(1, p / DATA_FILL_END)).count.
export const DATA_FILL_END = 0.55

const ROUNDS = 4
const PER_CELL = 5
const PER_ROUND = PERIMETER.length * PER_CELL // 40

// Cell visited by 0-based episode number e (0..159), plus which round it belongs to.
function episodeInfo(e) {
  const round = Math.floor(e / PER_ROUND) // 0..3
  const within = e % PER_ROUND
  const slot = Math.floor(within / PER_CELL)
  const order = round % 2 === 1 ? [...PERIMETER].reverse() : PERIMETER
  return { cell: order[slot], round: round + 1 }
}

// k in [0,1] -> how many of the 160 episodes are recorded at scrub position k, and the latest one.
export function episodeAt(k) {
  const kk = Math.min(1, Math.max(0, Number.isFinite(k) ? k : 0))
  const count = Math.round(kk * TOTAL_EPISODES)
  if (count <= 0) return { count: 0, index: -1, cell: null, round: null }
  const { cell, round } = episodeInfo(count - 1)
  return { count, index: count - 1, cell, round }
}

// Episodes recorded per cell after `count` episodes. B2 is always 0 (held out).
export function episodesPerCell(count) {
  const out = Object.fromEntries(CELLS.map((c) => [c, 0]))
  const n = Math.min(TOTAL_EPISODES, Math.max(0, Math.floor(count) || 0))
  for (let e = 0; e < n; e++) out[episodeInfo(e).cell] += 1
  return out
}

// Cell of a specific 0-based episode number (used by the 3D grid for arcs and dot order).
export function cellOfEpisode(e) {
  return episodeInfo(e).cell
}

// Protocol illustrations for the data chapter (not recorded positions):
//  - the recording path: a thin light that draws itself around the perimeter, round after round (reversals visible),
//  - the hold: faint tethers from the eight trained cells toward B2 that stop short, and an amber ring on B2.
import * as THREE from 'three'
import { PERIMETER, TOTAL_EPISODES, HELD_OUT } from './protocol.js'
import { cellCenter, TABLE_Y, GRID } from './layout.js'
import { PAL, mixL, isLightPal } from './palette.js'

const ROUNDS = 4
const SUB = 14 // vertices per hop, so the head advances smoothly
const smooth = (a, b, x) => { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t) }

export function createProtoViz(scene) {
  const group = new THREE.Group()
  group.visible = false
  scene.add(group)

  // ---- recording path: one continuous strip through the visit order of all four rounds ----
  const visits = []
  for (let r = 0; r < ROUNDS; r++) {
    const order = r % 2 === 1 ? [...PERIMETER].reverse() : PERIMETER
    order.forEach((c) => visits.push({ c, r }))
  }
  const pts = []
  const roundOf = [] // round index per vertex (colour is repainted on theme change)
  const cool = new THREE.Color()
  const warm = new THREE.Color()
  for (let i = 0; i < visits.length - 1; i++) {
    const a = cellCenter(visits[i].c), b = cellCenter(visits[i + 1].c)
    const round = visits[i].r
    const y = TABLE_Y + 0.004 + round * 0.0015
    const off = (round % 2 === 1 ? -1 : 1) * 0.0035 // reversed rounds run beside the forward ones
    for (let s = 0; s < SUB; s++) {
      const t = s / SUB
      const dx = b.x - a.x, dz = b.z - a.z
      const len = Math.hypot(dx, dz) || 1
      pts.push(a.x + dx * t - (dz / len) * off, y, a.z + dz * t + (dx / len) * off)
      roundOf.push(round)
    }
  }
  const last = cellCenter(visits[visits.length - 1].c)
  pts.push(last.x, TABLE_Y + 0.004 + (ROUNDS - 1) * 0.0015, last.z)
  roundOf.push(ROUNDS - 1)
  const cols = new Float32Array(roundOf.length * 3)
  const pathGeo = new THREE.BufferGeometry()
  pathGeo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3))
  pathGeo.setAttribute('color', new THREE.BufferAttribute(cols, 3))
  const pathMat = new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
  const pathLine = new THREE.Line(pathGeo, pathMat) // the whole trail so far, faint
  pathLine.frustumCulled = false
  pathLine.renderOrder = 5
  group.add(pathLine)
  const tailMat = pathMat.clone() // the most recent round, bright: reads as a light being drawn
  const tailGeo = new THREE.BufferGeometry() // shares the vertex data, has its own draw range
  tailGeo.setAttribute('position', pathGeo.getAttribute('position'))
  tailGeo.setAttribute('color', pathGeo.getAttribute('color'))
  const tailLine = new THREE.Line(tailGeo, tailMat)
  tailLine.frustumCulled = false
  tailLine.renderOrder = 5
  group.add(tailLine)
  const TAIL = 8 * SUB
  const total = pts.length / 3
  const head = new THREE.Mesh(new THREE.CircleGeometry(0.0055, 20).rotateX(-Math.PI / 2), new THREE.MeshBasicMaterial({ color: new THREE.Color(2.6, 2.4, 1.8), transparent: true, opacity: 0, depthWrite: false, toneMapped: false }))
  head.renderOrder = 7
  group.add(head)

  // ---- hold: tethers that stop short of B2 + an amber ring ----
  const b2 = cellCenter(HELD_OUT)
  const tPos = []
  const tFade = [] // alpha per vertex
  const stop = 0.62
  for (const id of PERIMETER) {
    const a = cellCenter(id)
    const SEG = 10
    for (let s = 0; s < SEG; s++) {
      const t0 = (s / SEG) * stop, t1 = ((s + 1) / SEG) * stop
      for (const t of [t0, t1]) tPos.push(a.x + (b2.x - a.x) * t, TABLE_Y + 0.0035, a.z + (b2.z - a.z) * t)
      const f0 = 1 - s / SEG, f1 = 1 - (s + 1) / SEG // fade toward the stopping point
      tFade.push(f0, f1)
    }
  }
  const tGeo = new THREE.BufferGeometry()
  tGeo.setAttribute('position', new THREE.Float32BufferAttribute(tPos, 3))
  const tCols = new Float32Array(tFade.length * 4)
  tGeo.setAttribute('color', new THREE.BufferAttribute(tCols, 4))
  const tMat = new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
  const tethers = new THREE.LineSegments(tGeo, tMat)
  tethers.frustumCulled = false
  tethers.renderOrder = 5
  group.add(tethers)

  const ringMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(1, 1, 1), transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
  const ring = new THREE.Mesh(new THREE.RingGeometry(0.93, 1, 96).rotateX(-Math.PI / 2), ringMat)
  ring.position.set(b2.x, TABLE_Y + 0.003, b2.z)
  ring.renderOrder = 6
  group.add(ring)
  const ringR = Math.hypot(GRID.d, GRID.w) * 0.42

  let painted = -1
  function repaint() {
    painted = PAL.stamp
