    dispose() {
      pathGeo.dispose(); tailGeo.dispose(); pathMat.dispose(); tailMat.dispose(); tGeo.dispose(); tMat.dispose(); ringMat.dispose(); ring.geometry.dispose()
      head.geometry.dispose(); head.material.dispose()
    },
  }
