    if (sig !== inst.sig) {
      inst.sig = sig;
      task.timeline = tp.timeline;
      inst.segs.innerHTML = tp.timeline.map((x) => `<span data-p="${x.phase}" style="flex-grow:${Math.max(0.001, x.t1 - x.t0)}" title="${phaseWord(x.phase)}"></span>`).join('');
    }
    const t = Math.max(0, Math.min(1, tp.t || 0));
    inst.head.style.left = `${(t * 100).toFixed(2)}%`;
    inst.segs.querySelectorAll('span').forEach((sp) => sp.classList.toggle('is-on', sp.dataset.p === tp.phase && usable));
    const pct = Math.round(t * 100);
    inst.track.setAttribute('aria-valuenow', String(pct));
    inst.track.setAttribute('aria-valuetext', usable ? `${phaseWord(tp.phase) || 'Done'}, ${pct}%` : 'No run yet');
    const playing = tp.running && !tp.paused;
    if (inst.playing !== playing) {
      inst.playing = playing;
      inst.play.innerHTML = playing ? PAUSE_I : PLAY_I;
      inst.play.setAttribute('aria-label', playing ? 'Pause' : 'Play');
    }
  }
  function wireScrub(inst) {
    const { track, play } = inst;
    const frac = (x) => { const r = track.getBoundingClientRect(); return (x - r.left) / r.width; };
    track.addEventListener('pointerdown', (e) => {
      if (!inst.enabled) return;
      e.preventDefault(); track.setPointerCapture(e.pointerId); task.dragging = true; scrubTo(frac(e.clientX));
    });
    track.addEventListener('pointermove', (e) => { if (task.dragging) scrubTo(frac(e.clientX)); });
    const end = () => { task.dragging = false; };
    track.addEventListener('pointerup', end); track.addEventListener('pointercancel', end);
    track.addEventListener('keydown', (e) => {
      if (!inst.enabled) return;
      // use the value we just sent while a scrub is in flight (the polled value can lag a frame or two)
      const now = performance.now() - (task.lastAt || 0) < 400 && task.last !== undefined ? task.last : Number(track.getAttribute('aria-valuenow')) / 100;
      const step = { ArrowLeft: -0.02, ArrowDown: -0.02, ArrowRight: 0.02, ArrowUp: 0.02, PageDown: -0.1, PageUp: 0.1 }[e.key];
      if (step !== undefined) { e.preventDefault(); scrubTo(now + step); }
      else if (e.key === 'Home') { e.preventDefault(); scrubTo(0); }
      else if (e.key === 'End') { e.preventDefault(); scrubTo(1); }
    });
    play.addEventListener('click', () => {
      if (!inst.enabled) return;
      const tp = stage.getTaskProgress();
      if (!tp) return;
      if (tp.running && !tp.paused) stage.pauseTask();
      else { if (tp.t >= 0.999) scrubTo(0); stage.resumeTask(); }
    });
    inst.phases.forEach((b) => b.addEventListener('click', () => jumpToPhase(b.dataset.p)));
  }
  function jumpToPhase(p) {
    const inst = instances.find((i) => i.variant === 'full');
    if (!inst?.enabled) return;
    const seg = (task.timeline.length ? task.timeline : stage.getTaskProgress()?.timeline || []).find((x) => x.phase === p);
    if (seg) scrubTo(seg.t0);
  }
  stage.onPhaseClick(jumpToPhase);

  function tick(now) {
    raf = 0;
    if (visibleCount <= 0) return;
    if (now - lastPoll >= interval) {
      lastPoll = now;
      const real = stage.real;
      const s = real && typeof real.getJointState === 'function' ? safeState(real) : null;
      if (s) instances.forEach((i) => { if (i.visible) paint(i, s); });
      const tp = stage.getTaskProgress();
      instances.forEach((i) => { if (i.variant === 'full' && i.visible) paintTask(i, tp); });
    }
    raf = requestAnimationFrame(tick);
  }
  function start() { if (!raf) raf = requestAnimationFrame(tick); }
  const safeState = (real) => { try { return real.getJointState(); } catch { return null; } };

  // 3D angle arcs on in sandbox/policies; phase words on in hero + sandbox; off elsewhere
  const want = { gauges: false, markers: true };
  const sent = { gauges: null, markers: null };
  function flush() {
    const real = stage.real;
    if (!real) return;
    if (sent.gauges !== want.gauges && typeof real.setJointGauges === 'function') { real.setJointGauges(want.gauges); sent.gauges = want.gauges; }
    if (sent.markers !== want.markers && typeof real.setPhaseMarkers === 'function') { real.setPhaseMarkers(want.markers); sent.markers = want.markers; }
  }
  document.addEventListener('chapterchange', (e) => {
    want.gauges = e.detail === 'sandbox' || e.detail === 'policies';
    want.markers = e.detail === 'sandbox' || e.detail === 'hero';
    flush();
  });
  document.addEventListener('visibilitychange', () => { if (!document.hidden && visibleCount > 0) start(); });

  make($('.chapter--hero'), 'hero');
  make($('#policies .policies-hud'), 'compact');
  const sbHost = $('#sandbox .sandbox-hud');
  make(sbHost, 'full');
  return {
    resync() { sent.gauges = null; sent.markers = null; flush(); if (visibleCount > 0) start(); },
  };
}

import { THEMES, DEFAULT_THEME, themeFromURL } from '../themes.js';

// Applies a theme's palette to :root and derives every secondary token from it (scrims, shadows, text-safe
// accents, glow strengths), so no stylesheet needs to know which theme is active.

const hexToRgb = (h) => {
  const v = h.replace('#', '');
  const n = v.length === 3 ? v.split('').map((c) => c + c).join('') : v;
  return [0, 2, 4].map((i) => parseInt(n.slice(i, i + 2), 16));
};
const toHex = (rgb) => `#${rgb.map((c) => Math.round(Math.max(0, Math.min(255, c))).toString(16).padStart(2, '0')).join('')}`;
const lin = (c) => { const s = c / 255; return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4; };
const lum = (rgb) => 0.2126 * lin(rgb[0]) + 0.7152 * lin(rgb[1]) + 0.0722 * lin(rgb[2]);
const contrast = (a, b) => { const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x); return (hi + 0.05) / (lo + 0.05); };
const mix = (a, b, t) => a.map((c, i) => c + (b[i] - c) * t);

// Nudge `fg` toward `toward` until it reads on `bg` (used for accents that appear as text).
function readable(fg, bg, toward, min = 4.5) {
  let out = fg;
  for (let t = 0; t <= 1 && contrast(out, bg) < min; t += 0.04) out = mix(fg, toward, t);
  return out;
}

const list = (rgb) => rgb.map(Math.round).join(', ');

export function deriveTokens(css) {
  const c = Object.fromEntries(Object.entries(css).map(([k, v]) => [k, hexToRgb(v)]));
  const wall = c['--wall'], wall2 = c['--wall-2'], ivory = c['--ivory'];
  const light = lum(ivory) < lum(wall); // dark ink on a light page
  const ink = light ? ivory : wall2;    // the darkest end of the palette
  const paper = light ? wall : ivory;   // the lightest end
  const onAccent = contrast(c['--noodle'], wall2) >= contrast(c['--noodle'], ivory) ? wall2 : ivory;
  const t = {};
  Object.entries(c).forEach(([k, v]) => { t[`${k}-rgb`] = list(v); });
  t['--veil-rgb'] = list(light ? wall : wall2);
  t['--shadow-rgb'] = light ? '38, 50, 64' : '0, 0, 0';
  t['--shadow-a'] = light ? '0.24' : '0.9';
  t['--on-accent'] = toHex(onAccent);
  t['--accent-text'] = toHex(readable(c['--noodle'], wall, ink));
  t['--held-text'] = toHex(readable(c['--held'], wall, ink));
  t['--trained-text'] = toHex(readable(c['--trained'], wall, ink));
  t['--glow-a'] = light ? '0.28' : '0.5';
  t['--grain-a'] = light ? '0.05' : '0.055';
  t['--caption'] = `rgba(${list(ivory)}, ${light ? 0.82 : 0.74})`;
  t['--seg-idle'] = `rgba(${list(ivory)}, ${light ? 0.82 : 0.78})`;
  t['--paper-rgb'] = list(paper);
  return { tokens: t, light };
}

let current = DEFAULT_THEME;
export const currentTheme = () => current;

export function applyTheme(name, { updateURL = false } = {}) {
  const key = THEMES[name] ? name : DEFAULT_THEME;
  const theme = THEMES[key];
  const root = document.documentElement;
  const { tokens, light } = deriveTokens(theme.css);
  Object.entries(theme.css).forEach(([k, v]) => root.style.setProperty(k, v));
  Object.entries(tokens).forEach(([k, v]) => root.style.setProperty(k, v));
  // The loader ring keeps the stage's ring colour unless that would vanish against the loader background.
  const ring = hexToRgb(theme.stage.ring), bg = hexToRgb(theme.css['--wall-2']);
  const ringUse = contrast(ring, bg) >= 1.8 ? ring : hexToRgb(theme.css['--noodle']);
  root.style.setProperty('--ring-color', toHex(ringUse));
  root.style.setProperty('--ring-rgb', list(ringUse));
  root.dataset.theme = key;
  root.dataset.mode = light ? 'light' : 'dark';
  root.style.colorScheme = light ? 'light' : 'dark';
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', theme.css['--wall-2']);
  if (updateURL) {
    const url = new URL(location.href);
    url.searchParams.set('theme', key);
    history.replaceState(null, '', url);
  }
  current = key;
  return key;
}

export { THEMES, themeFromURL };

// Review-only switcher (?themes): four swatch dots with names, bottom-left. Switches page and stage live.
export function initThemeSwitcher(onChange) {
  const bar = document.createElement('div');
  bar.className = 'theme-switcher';
  bar.setAttribute('role', 'group');
  bar.setAttribute('aria-label', 'Theme');
  Object.entries(THEMES).forEach(([key, t]) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.dataset.theme = key;
    b.setAttribute('aria-pressed', String(key === current));
    b.innerHTML = `<i style="background:linear-gradient(135deg, ${t.css['--wall']} 45%, ${t.css['--noodle']} 45% 70%, ${t.css['--held']} 70%)"></i><span>${t.label}</span>`;
    b.addEventListener('click', () => {
      applyTheme(key, { updateURL: true });
      bar.querySelectorAll('button').forEach((x) => x.setAttribute('aria-pressed', String(x === b)));
      onChange?.(key);
    });
    bar.append(b);
  });
  document.body.append(bar);
}
